const HMK_CREATION_REACH_KEY='hmk-ledger-creation-reached-v1:';
function creationReachableStep(actor,creation){
 if(!actor?.id)return Math.max(1,Number(creation?.step)||1);
 const key=HMK_CREATION_REACH_KEY+actor.id;
 let previous=1;
 try{previous=Number(localStorage.getItem(key))||1}catch{}
 const completed=Math.max(0,...Object.keys(creation?.completed||{}).filter(k=>creation.completed[k]).map(Number).filter(Number.isInteger));
 const terminal=['auto-generated','review-required','complete'].includes(creation?.status)?14:1;
 const reached=Math.max(1,previous,Number(creation?.step)||1,completed,terminal);
 const safe=Math.min(14,reached);
 if(safe>previous){try{localStorage.setItem(key,String(safe))}catch{}}
 return safe;
}
function folioChapterParts(body,kind=''){
 const nodes=folioHTMLNodes(body);
 if(kind.includes('journal-book--sheet-inventory')){
  // Arsenal has a fixed split. The load summary and its complete add-item form
  // always stay on the right folio regardless of inventory length.
  return [nodes.slice(0,1).map(x=>x.outerHTML).join(''),nodes.slice(1).map(x=>x.outerHTML).join('')];
 }
 if(kind.includes('journal-book--characters')){
  const gallery=nodes.find(x=>x.classList.contains('character-gallery'));
  if(gallery){
   const groups=[...gallery.querySelectorAll(':scope > .character-registry-group')];
   const cards=groups.length?groups.flatMap(group=>[...group.querySelectorAll(':scope > .folio-character-list > .character-card')].map(card=>({kind:group.dataset.characterKind,html:card.outerHTML}))):[...gallery.children].map(card=>({kind:'PC',html:card.outerHTML}));
   const firstPageCount=Math.min(4,cards.length);
   const pre=nodes.filter(x=>x!==gallery).map(x=>x.outerHTML).join('');
   const groupedPage=entries=>['PC','NPC'].map(kind=>{const matches=entries.filter(c=>c.kind===kind);return matches.length?`<section class="character-registry-group" data-character-kind="${kind}"><h3 class="character-group-heading">${kind} <small>(${matches.length})</small></h3><div class="folio-character-list">${matches.map(c=>c.html).join('')}</div></section>`:'';}).join('');
   return [pre+groupedPage(cards.slice(0,firstPageCount)),groupedPage(cards.slice(firstPageCount))];
  }
  return [nodes.filter(x=>!x.classList.contains('empty')).map(x=>x.outerHTML).join(''),
   nodes.filter(x=>x.classList.contains('empty')).map(x=>x.outerHTML).join('')];
 }
 if(kind.includes('journal-book--library')){
  const tableWrap=nodes.find(e=>e.classList.contains('library-table-wrap'));
  const table=tableWrap?.querySelector('table.library-table');
  if(table){
   const headers=[...(table.tHead?.rows[0]?.cells||[])].map(x=>x.textContent.trim());
   const cards=[...(table.tBodies[0]?.rows||[])].map(x=>folioLibraryEntry(x,headers));
   const tableIndex=nodes.indexOf(tableWrap);
   const pre=nodes.slice(0,tableIndex).map(x=>x.outerHTML).join('');
   const post=nodes.slice(tableIndex+1).map(x=>x.outerHTML).join('');
   const middle=Math.ceil(cards.length/2);
   return [pre+`<div class="folio-catalog-list">${cards.slice(0,middle).join('')}</div>`,
    `<div class="folio-catalog-list">${cards.slice(middle).join('')}</div>`+post];
  }
  const panel=nodes.find(e=>e.matches('section.panel')&&e.querySelector('.library-rules-details'));
  if(panel){
   const entries=[...panel.children].filter(x=>x.matches('.library-rules-details'));
   if(entries.length>1){
    const halfway=Math.ceil(entries.length/2);
    const heading=[...panel.children].filter(x=>!entries.includes(x)).map(x=>x.outerHTML).join('');
    return [nodes.filter(x=>x!==panel).map(x=>x.outerHTML).join('')+`<section class="folio-rules-group">${heading}${entries.slice(0,halfway).map(x=>x.outerHTML).join('')}</section>`,
     `<section class="folio-rules-group">${entries.slice(halfway).map(x=>x.outerHTML).join('')}</section>`];
   }
  }
 }
 if(kind.includes('journal-book--skills')){
  const workbench=nodes.find(x=>x.classList.contains('hmk-skill-workbench'));
  if(workbench){
   const workChildren=[...workbench.children];
   const split=workChildren.findIndex(x=>x.classList.contains('hsk-separated-tests'));
   if(split!==-1){
    const head=workChildren.slice(0,split).map(x=>x.outerHTML).join('');
    const tests=workChildren.slice(split).map(x=>x.outerHTML).join('');
    return [head+nodes.filter(x=>x!==workbench).map(x=>x.outerHTML).join(''),tests];
   }
  }
 }
 if(kind.includes('journal-book--creation')){
  const flow=nodes.find(x=>x.classList.contains('creation-flow'));
  if(flow){
   const parts=[...flow.children];
   const formIndex=parts.findIndex(x=>x.matches('form#creation-step-form'));
   if(formIndex!==-1){
    const actor=selected?character(selected):null;
    const creation=actor?creationOf(actor):null;
    const activeStep=creation?.step??1;
    const current=CHARACTER_STEPS[activeStep-1]??['Character Creation','—'];
    // Highest legitimately reached step is a UI-only bookmark. It survives an
    // Edit jump back to Folk, unlike creation.completed which is intentionally
    // invalidated by applyCreationPatch. Character data stay authoritative.
    const reachable=creationReachableStep(actor,creation);
    const revision=actor?creationRevisionIssues(actor):[];
    const stages=CHARACTER_STEPS.map(([name,page],index)=>{
     const number=index+1;
     const ui=creationUIStatus(actor?.id,number);
     // The very first visit to a new step is *in progress*, not a defect.
     // Revision issues become red for previously confirmed/revisited steps.
     const needsReview=revision.some(x=>x.step===number)&&number<=reachable&&
      (Boolean(creation?.completed?.[number])||number!==activeStep||reachable>activeStep||ui?.kind==='invalid');
     // A current form may differ from the already-confirmed saved version.
     // For Grace/Marked, never show a tick while Divine Aspect is missing.
     const activeForm=parts[formIndex];
     const pendingAspect=number===14&&number===activeStep&&(()=>{
      const grace=Number(activeForm.querySelector('[name="graceDie"]')?.value??creation?.values?.graceProof?.roll);
      const aspect=String(activeForm.querySelector('[name="graceAspect"]')?.value||'').trim();
      return Number.isFinite(grace)&&grace>=15&&grace<=20&&!aspect;
     })();
     const hasError=Boolean(needsReview||ui?.kind==='invalid'||pendingAspect);
     const dirty=ui?.kind==='editing'&&!hasError;
     const confirmed=Boolean(creation?.completed?.[number])&&!hasError&&!dirty;
     const state=hasError?'invalid':dirty?'editing':confirmed?'complete':number===activeStep?'active':'pending';
     const status=hasError?'Vyžaduje opravu':dirty?'Změna čeká na potvrzení':confirmed?'Dokončeno':number===activeStep?'Aktuální krok':number<=reachable?'Dříve navštíveno':'Dosud nepřístupné';
     const inner=`<span class="folio-creation-step__number">${number}</span><span class="folio-creation-step__label">${esc(name)}</span><span class="folio-creation-step__page">str. ${esc(page)}</span><span class="folio-visually-hidden">${status}</span>`;
     return `<li class="folio-creation-step folio-creation-step--${state}${number<=reachable?' folio-creation-step--visited':''}${needsReview?' folio-creation-step--review':''}" data-creation-step-row="${number}"${number===activeStep?' aria-current="step"':''}>${number<=reachable?`<button type="button" class="folio-creation-step__link" data-creation-step="${number}" ${number===activeStep?'aria-current="step"':''} aria-label="${esc(status)} · Otevřít krok ${number}: ${name}">${inner}</button>`:`<span class="folio-creation-step__locked" aria-disabled="true">${inner}</span>`}</li>`;
    }).join('');
    const outline=`<details class="folio-creation-index" aria-label="Přehled pravidlové tvorby"${window.innerWidth>550?' open':''}><summary class="folio-creation-index__heading">Kapitoly tvorby <span>14 kroků</span></summary><ol class="folio-creation-index__steps">${stages}</ol><p class="folio-creation-index__note">Kliknutím lze otevřít aktuální a dříve navštívené kapitoly. Budoucí kroky odemkne pravidlový průvodce postupně; změny v předchozích krocích mohou vyžadovat nové ověření navazujících hodnot.</p></details>`;
    // Highlight the exact active form field when its prior evidence was
    // invalidated. On a first-time step, do not show a red error before any
    // user interaction. A revisited step is marked until the normal HMK
    // validator successfully confirms it.
    const localIssues=revision.filter(i=>i.step===activeStep);
    const revisited=reachable>activeStep;
    if((revisited||activeStep===14)&&localIssues.length){
     for(const issue of localIssues){
      const form=parts[formIndex];
      const field=[...form.querySelectorAll('input,select,textarea,button')].find(el=>el.name===issue.field||el.id===issue.field);
      const target=field?.closest('label,fieldset')||field||form.querySelector('.creation-inputs');
      if(target){target.classList.add('folio-creation-revision-target');if(field){field.classList.add('folio-creation-revision-control');field.setAttribute('aria-invalid','true');}}
     }
    }
    // A consistent two-row label layout regardless of long Czech/English names,
    // optional ? button, or wrapped text. Do not touch checkbox/radio labels.
    // This only transforms the rendered DOM; the original form input/name stays
    // inside its label and keeps its normal submit/validation semantics.
    for(const label of parts[formIndex].querySelectorAll('label')){
     const direct=[...label.children].filter(el=>el.matches('input:not([type="hidden"]),select,textarea'));
     if(direct.length!==1||['checkbox','radio'].includes(direct[0].type))continue;
     const control=direct[0];
     const prefix=[];
     for(const node of [...label.childNodes]){if(node===control)break;prefix.push(node);}
     if(!prefix.length)continue;
     const head=document.createElement('span');head.className='hmk-creation-field-heading';
     prefix.forEach(node=>head.appendChild(node));
     label.insertBefore(head,control);
     label.classList.add('hmk-creation-aligned-label');
    }
    const revisionPanel=activeStep===14?
     `<section class="folio-creation-revision" aria-label="Závěrečná revize tvorby"><h4>Revize tvorby · kroky 1–14</h4>${revision.length?`<p>Tyto kroky obsahují neověřené nebo změnou zneplatněné údaje. Otevřete je, opravte červeně označená pole a krok znovu potvrďte.</p><ol>${revision.map(i=>`<li><button type="button" class="folio-creation-revision-link" ${i.step===activeStep?`data-creation-review-focus="${esc(i.field||'')}"`:`data-creation-step="${i.step}"`}><strong>Krok ${i.step} · ${esc(i.title)}</strong><span>${esc(i.message)}</span></button></li>`).join('')}</ol>`:`<p>Dosavadní kroky jsou potvrzené. Závěrečné uložení ještě provede pravidlové kontroly HMK.</p>`}</section>`:
     revisited&&localIssues.length?`<p class="folio-creation-revision-current" role="status">Vyžaduje opravu: ${esc(localIssues.map(i=>i.message).join(' '))}</p>`:'';
    const intro=parts.slice(0,formIndex).map(x=>x.outerHTML).join('');
    const interactive=parts.slice(formIndex).map(x=>x.outerHTML).join('');
    const left=`<section class="panel wide creation-flow creation-flow--folio creation-flow--context">${intro}${outline}</section>`;
    const right=`<section class="panel wide creation-flow creation-flow--folio creation-flow--action"><header class="folio-creation-active"><div class="folio-creation-active__eyebrow">Krok ${activeStep} z 14 · HMK v1.2</div><h3>${esc(current[0])}</h3><span class="folio-creation-active__source">Tištěná strana ${esc(current[1])}</span>${activeStep===12?`<span class="folio-creation-active__stage">Stadium Skills: ${esc((SKILL_STAGES[creation?.skillStage]??'aktuální'))}</span>`:''}</header>${revisionPanel}${interactive}</section>`;
    return [left,right];
   }
  }
 }
 const root=nodes.length===1&&nodes[0].classList.contains('journal-tech-columns')?[...nodes[0].children]:nodes;
 return folioBalancedParts(root);
}
function folioChapterSpread(title,subtitle,body,kind=''){
 const [left,right]=folioChapterParts(body,kind);
 const header=`<header class="folio-chapter-heading"><h3>${esc(title)}</h3>${subtitle?`<p>${esc(subtitle)}</p>`:''}</header>`;
 const pages=`<section class="journal-book-page journal-book-page--left folio-chapter-page" aria-label="Levá stránka: ${esc(title)}">${header}<div class="folio-chapter-content">${left}</div></section><section class="journal-book-page journal-book-page--right folio-chapter-page" aria-label="Pravá stránka: ${esc(title)}"><div class="folio-chapter-content folio-chapter-content--right">${right}</div></section>`;
 // Skill tab controls need the same .hmk-skill-workbench ancestor as before.
 return `<div class="journal-book-spread folio-chapter-spread${kind.includes('journal-book--skills')?' hmk-skill-workbench':''}"${kind.includes('journal-book--skills')?' id="hmk-skill-workbench"':''}>${pages}</div>`;
}
function journalShell(inner,extraClass='',showSubnav=true){
 if(extraClass.includes('journal-book--chapter')&&showSubnav){
  // Existing character's Inventory/Conditions/Notes chapters use precisely the
  // same dual-page renderer. Keep character-only subnavigation in place.
  const nodes=folioHTMLNodes(inner),shell=nodes.find(x=>x.classList.contains('journal-technical-shell'));
  if(shell){
   const heading=shell.querySelector('.journal-alt-header');
   const title=heading?.querySelector('h3')?.textContent||'Character Sheet';
   const subtitle=heading?.querySelector('p')?.textContent||'';
   const content=shell.querySelector('.journal-tech-columns')?.innerHTML||shell.innerHTML;
   inner=folioChapterSpread(title,subtitle,content,title==='Arsenal & Gear'?'journal-book--sheet-inventory':'journal-book--sheet-chapter');
  }
 }
 return `<section class="journal-book panel wide ${extraClass}"><div class="journal-book-frame"><div class="hmk-book-decor" aria-hidden="true"><i class="hmk-rail hmk-rail--top"></i><i class="hmk-rail hmk-rail--bottom"></i><i class="hmk-rail hmk-rail--left"></i><i class="hmk-rail hmk-rail--right"></i><i class="hmk-frame-jewel hmk-frame-jewel--top"></i><i class="hmk-frame-jewel hmk-frame-jewel--bottom"></i><i class="hmk-frame-side hmk-frame-side--left"></i><i class="hmk-frame-side hmk-frame-side--right"></i></div><div class="book-cover-ornament book-cover-ornament--tl" aria-hidden="true"></div><div class="book-cover-ornament book-cover-ornament--tr" aria-hidden="true"></div><div class="book-cover-ornament book-cover-ornament--bl" aria-hidden="true"></div><div class="book-cover-ornament book-cover-ornament--br" aria-hidden="true"></div>${showSubnav?journalSectionNav():''}${inner}</div></section>`;
}
function journalChapterShell(title,subtitle,body,extraClass=''){
 return journalShell(folioChapterSpread(title,subtitle,body,extraClass),`journal-book--chapter ${extraClass}`,false);
}
function creationBookView(){
 const c=selected?character(selected):null;
 if(!c)return journalChapterShell('Pravidlová tvorba postavy','Průvodce je navázán na konkrétní postavu v registru.',`<div class="empty">Nejprve v registru otevřete nebo založte konkrétní postavu. Poté bude dostupná kompletní 14kroková pravidlová tvorba HMK 1:1.</div>`,'journal-book--creation');
 return journalChapterShell('Pravidlová tvorba postavy',`${c.name} · 14 kroků podle HMK v1.2`,creationWizardView(),'journal-book--creation');
}
function characterJournalHero(c,inv,editing=false){
 const h=c.hmk||{},creation=h.creation?.values||{},state=persistentStateOf(c),attrs=h.attributes||{};
 const bio=(key,...fallbacks)=>firstPresent(h[key],...fallbacks,creation[key],'—');
 const lineageRows=[['Name',c.name],['Race / Folk',bio('folk')],['Age group',bio('ageGroup')],['Birthdate',bio('birthdate')],['Sunsign',bio('sunsign')],['Birthplace',bio('birthplace')],['Social Class',bio('socialClass')],['Background',bio('background')]];
 const appearanceRows=[['Height',bio('height')],['Weight',bio('weight')],['Hair',bio('hair')],['Eyes',bio('eyes')],['Complexion',bio('complexion')],['Handedness',bio('handedness')],['Deportment',bio('deportment')]];
 const familyRows=[['Society',bio('society')],['Family',bio('familyOccupation')],['Occupation',firstPresent(c.occupation,bio('occupation'))],['Home',bio('home')],['Realm',bio('realm')],['Settlement',bio('settlement')],['Wealth',bio('wealth')],['Coins',cashForCharacter(c).ok?cashForCharacter(c).balance:bio('coins')],['Estrangement',bio('estrangement')],['Pantheon',bio('pantheon')],['Region',bio('birthRegion')],['Languages',h.regionalLanguages?.length?listPresent(h.regionalLanguages):bio('nativeLanguage')]];
 const traitValues=[bio('psyche'),bio('estrangement'),bio('pantheon'),creation.autoGeneration?.semantic?.summary,c.description].filter(v=>v&&v!=='—');
 const move=Number.isFinite(attrs.agl)&&Number.isFinite(attrs.str)?baseMove({agility:attrs.agl,strength:attrs.str,folk:String(h.folk||'').toLowerCase().includes('kuzhai')?'kuzhai':'human-sized'}):null;
 const load=resolveCombatantLoad({character:c,inventory:activeRationInventory()});
 const combatSkills=[['Initiative',skillValueForJournal(c,['Initiative'])],['Awareness',skillValueForJournal(c,['Awareness'])],['Dodge',skillValueForJournal(c,['Dodge'])],['Shield',skillValueForJournal(c,['Shield'])],['Melee',skillValueForJournal(c,['Sword','Melee','Axe','Spear'])],['Missile',skillValueForJournal(c,['Archery','Missile','Bow'])],['Mounted',skillValueForJournal(c,['Riding'])],['Unarmed',skillValueForJournal(c,['Unarmed'])]];
 const encumbrance=[['Armour',load.armourENC??'—'],['Gear',load.gearENC??'—'],['Str Mod',load.strengthModifier??'—'],['Enc',load.modifiedENC??'—'],['Shock',state.shock??0]];
 const movement=[['Base',move?.move??'—'],['Effective',move?.move??'—'],['Half',move?Math.floor(move.move/2):'—'],['Full',move?.move??'—'],['Double',move?move.move*2:'—']];
 const trauma=[['Fatigue',combatFatigueTotals(state).total],['Stress',firstPresent(state.morale?.psycheStress,0)],['Shock',firstPresent(state.shock,0)],['Wounds',firstPresent((state.wounds||[]).length,(h.injuries||[]).length,0)],['Injuries',firstPresent((h.injuries||[]).length,0)]];
 const physical=HMK_ATTRIBUTES.PHYSICAL.map(([key,label])=>[label,attrs[key]??'—',key]);
 const mental=HMK_ATTRIBUTES.MENTAL.map(([key,label])=>[label,attrs[key]??'—',key]);
 const gracePiety=[['Grace',h.divineGrace?.grace??h.grace??'—'],['Piety',h.piety??'—'],['Doctrine',h.doctrine??'—'],['Blessing',h.blessing??'—'],['Morality',bio('morality')]];
 const fateRoll=Number.isFinite(h.fateML)?h.fateML:'—';
 const fateFP=Number.isFinite(h.fatePoints)?h.fatePoints:'—';
 const meleeRows=journalWeaponRows(inv,'melee',c);
 const missileRows=journalWeaponRows(inv,'missile',c);
 const armourRows=inventoryRowsForJournal(inv,'armour');
 const possessionRows=inventoryRowsForJournal(inv,'possessions');
 const abilities=(h.abilities||h.spells||[]);
 const abilityRows=abilities.length?abilities.map(x=>[typeof x==='string'?x:(x.name||x.title||'Ability'),typeof x==='string'?'—':(x.level||x.notes||'—')]):[['—','—'],['—','—'],['—','—']];
 const injuryStateRows=[['Current Shock',firstPresent(state.shock,0)],['Shock Save',skillValueForJournal(c,['Shock'])],['Unconscious',state.unconscious?'Yes':'No'],['Death Save',state.death?'Pending':'—']];
 const conditionRows=[['Poisoned',state.poisoned?'Yes':'No'],['Diseased',state.diseased?'Yes':'No'],['Cursed',state.cursed?'Yes':'No'],['Winded',state.winded?'Yes':'No'],['Weary',state.weary?'Yes':'No'],['Fatigued',combatFatigueTotals(state).total]];
 const notes=[c.description,traitValues[0],traitValues[1]].filter(Boolean).join(' · ')||'No personal notes entered.';
 return journalShell(`${editing?'<form id="sheet-inline-form" class="sheet-inline-form journal-edit-spread">':''}<div class="journal-book-spread"><section class="journal-book-page journal-book-page--left"><header class="journal-nameplate"><div class="journal-crest">⚜</div><div class="journal-nameplate-copy"><h3>${editing?`<label class="journal-name-edit-label">Jméno postavy<input class="journal-name-edit-input" name="sheet_character_name" type="text" maxlength="120" required value="${esc(c.name)}" aria-label="Jméno postavy"></label>`:esc(c.name)}</h3><p>${esc((c.occupation||bio('standing')||'Wayfarer')).toUpperCase()}</p><div class="journal-nameplate-minor">${esc(bio('folk'))} &nbsp; ✦ &nbsp; ${esc(bio('society'))} &nbsp; ✦ &nbsp; ${esc(bio('background'))}</div></div></header><div class="journal-left-top">${journalSectionTable('Birth & Origins',lineageRows)}<div class="journal-portrait-panel"><div class="sheet-portrait sheet-portrait--book">${sheetPortraitHTML(c)}</div></div>${journalSectionTable('Appearance',appearanceRows,'journal-appearance')}</div><div class="journal-left-mid">${journalSectionTable('Family & Links',familyRows,'',editing)}<section class="journal-book-section"><div class="journal-book-title">Traits & Character</div>${traitValues.length?`<ul class="journal-trait-list">${traitValues.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`:'<p class="muted">Bez zaznamenaných rysů.</p>'}</section></div><div class="journal-attributes-row">${journalStatBoxes('Physical Attributes',physical,editing)}${journalStatBoxes('Mental Attributes',mental,editing)}${journalGracePietyBoxes(gracePiety,fateRoll,fateFP)}</div>${editing?`<section class="journal-book-section journal-book-section--skills journal-inline-skills"><div class="journal-book-title">Skills · Edit <span class="journal-book-hint">DP, SB, SM a ML</span></div>${characterCalculationHTML(c,{editing:true,embedded:true})}</section>`:journalSkillColumnsHTML(c)}${journalConvocationsHTML(c)}</section><section class="journal-book-page journal-book-page--right"><div class="journal-right-top-grid">${journalSectionTable('Combat Skills',combatSkills,'journal-book-section--tight')}${journalSectionTable('Encumbrance',encumbrance,'journal-book-section--tight')}${journalSectionTable('Movement',movement,'journal-book-section--tight')}${journalSectionTable('Trauma & Conditions',trauma,'journal-book-section--tight')}</div>${journalInventoryTable('Melee Weapons',['Weapon','WQ','HFT','RCH','ATK','DEF','ZD','IMP','TA'],meleeRows,'journal-weapon-table')}${journalInventoryTable('Missile Weapons',['Weapon','WQ','DRW','BR','ATK','PRJ','ZD','IMP','TA'],missileRows,'journal-weapon-table')}<div class="journal-right-mid-grid">${journalInventoryTable('Armour & Clothing',['Item','ENC','WQ','Notes'],armourRows,'journal-right-card')}${journalBodyLocationsHTML(c)}</div><div class="journal-right-low-grid">${journalInventoryTable('Possessions',['Item','Qty','lb','Notes'],possessionRows,'journal-right-card')}${journalInventoryTable('Spells & Abilities',['Name','Notes'],abilityRows,'journal-right-card')}</div><div class="journal-right-bottom-grid">${journalSectionTable('Shock & Injury',injuryStateRows,'journal-right-card')}${journalSimpleChecklist('Conditions',conditionRows)}<section class="journal-book-section journal-notes-card"><div class="journal-book-title">Notes</div><p>${esc(notes)}</p></section></div>${journalConditionDetailsHTML(c,state,load)}</section></div>${editing?'</form>':''}`,`journal-book--overview`)
}
function equippedHandsPanel(inv,character){
 const handedness=character?.hmk?.handedness;
 const mainRight=handedness==='right';
 const show=(slot,label)=>{
  const actual=inv.find(x=>x.slot===slot);
  const other=inv.find(x=>x.slot===(slot==='main_hand'?'off_hand':'main_hand'));
  const reserved=other&&requiresTwoHands(other);
  const choices=inv.filter(x=>x.id!==actual?.id&&!x.destroyed&&isHandheldItem(x)&&
   ['none','carried'].includes(x.slot??'none')&&Number.isSafeInteger(x.quantity)&&x.quantity>0);
  const gripSelector=actual?.snapshot?.category==='weapon'&&supportsSelectableTwoHandGrip(actual)&&!actual.snapshot.properties?.twoHanded&&!actual.snapshot.properties?.verifiedModes?.[0]?.twoHanded?
   `<label class="hmk-grip-slot"><span>Držení ${esc(actual.snapshot.name)}</span><select data-weapon-grip="${esc(actual.id)}" aria-label="Držení ${esc(actual.snapshot.name)}" ${combatInitiativeSequence?'disabled':''}><option value="one" ${gripOf(actual)==='one'?'selected':''}>Jednoručně</option><option value="two" ${gripOf(actual)==='two'?'selected':''}>Obouručně</option></select></label>`:actual?.snapshot?.category==='weapon'&&requiresTwoHands(actual)?'<small>Držení: obouručně (povinné)</small>':'';
  return `<div class="hmk-hand-control"><label class="hmk-hand-slot"><strong>${esc(label)}</strong><select data-equip-hand="${esc(slot)}" aria-label="${esc(label)} – vybavení z inventáře" ${combatInitiativeSequence?'disabled title="Změny výbavy během Initiative vyžadují Combat akci"':''}><option value="">${reserved?'Vyhrazeno obouruční zbrani':`Volná${actual?' (odložit do inventáře)':''}`}</option>${actual?`<option selected value="${esc(actual.id)}">${esc(actual.snapshot?.name||'Nasazený předmět')}</option>`:''}${!reserved?choices.map(x=>`<option value="${esc(x.id)}">${esc(x.snapshot?.name||'Předmět')}${x.quantity>1?' · 1 z '+x.quantity:''}${requiresTwoHands(x)?' · obouruč':''}</option>`).join(''):''}</select></label>${gripSelector||''}</div>`;
 };
 return `<div class="equipment-summary equipped-hands" aria-label="Aktuální obsazení rukou">${handedness==='right'||handedness==='left'?show(mainRight?'off_hand':'main_hand','Levá ruka')+show(mainRight?'main_hand':'off_hand','Pravá ruka'):show('main_hand','Hlavní ruka – fyzická strana neurčena')+show('off_hand','Vedlejší ruka – fyzická strana neurčena')}</div>`;
}
function characterInventoryOverview(c,inv){
 const sourceRows=projectInventoryRows(activeRationInventory().filter(item=>item.characterId===c.id));
 const rows=sourceRows,totals=inventoryTotals(sourceRows);
 const onPerson=inventoryTotals(sourceRows.filter(r=>r.kind!=='chest'));const stored=inventoryTotals(sourceRows.filter(r=>r.kind==='chest'));
 const load=resolveCombatantLoad({character:c,inventory:activeRationInventory()});
 const number=x=>Number.isFinite(x)?String(x):'—';
 const cards=[['Předmětů',sourceRows.reduce((sum,r)=>sum+(r.qty||0),0)],['Zjištěná hodnota',totals.knownValue+' d'+(totals.unknownValue?` · ${totals.unknownValue} bez ceny`:'')],
  ['Hmotnost majetku (včetně Truhlice)',totals.knownWeightLb.toFixed(1)+' lb'+(totals.unknownWeight?` · ${totals.unknownWeight} bez váhy`:'')],
  ['Nesené / vybavené položky',onPerson.knownWeightLb.toFixed(1)+' lb'+(onPerson.unknownWeight?' · neznámé váhy':'' )],['Efektivní výbava pro Gear ENC',Number.isFinite(load.gearLoad?.effectiveLb)?`${load.gearLoad.effectiveLb.toFixed(1)} lb`:'neurčeno'],['V Truhlici',stored.knownWeightLb.toFixed(1)+' lb'+(stored.unknownWeight?' · neznámé váhy':'')],['ENC zbroje',load.armourENC!==null?number(load.armourENC):Number.isFinite(load.knownArmourENC)?`${load.knownArmourENC}${Number.isFinite(load.armourENCUpperBound)&&load.armourENCUpperBound!==load.knownArmourENC?'–'+load.armourENCUpperBound:''} (odhad rozsahu)`: 'nedoloženo'],['Gear ENC',number(load.gearENC)],['Upravené ENC',load.encReady?number(load.modifiedENC):Number.isFinite(load.knownMinimumENC)?`${load.knownMinimumENC}${Number.isFinite(load.knownMaximumENC)&&load.knownMaximumENC!==load.knownMinimumENC?'–'+load.knownMaximumENC:''} ${load.prohibitedOutfit?'(zakázané vrstvy)':'(rozsah)'}`:'neurčeno'],
  ['Bulk H / P / T / N',load.bulkReady?['head','arms','torso','legs'].map(z=>number(load.bulkByZone[z])).join(' / '):load.prohibitedOutfit?'zakázané vrstvy':'pořadí neurčeno'],
  ['Hotovost',cashForCharacter(c).ok?cashForCharacter(c).balance+' d':'neurčena']];
 const invHelp={
  'Předmětů':'Počet skutečných kusů v inventáři včetně Truhlice. Každý inventární záznam je zobrazen na vlastním řádku.',
  'Zjištěná hodnota':'Součet ověřených katalogových cen. Neznámé ceny se nedopočítávají.',
  'Hmotnost majetku (včetně Truhlice)':'Součet všech doložených fyzických hmotností, včetně uložených věcí.',
  'Nesené / vybavené položky':'Hmotnost předmětů fyzicky u postavy, bez věcí v truhlici.',
  'Efektivní výbava pro Gear ENC':'Jen skutečně nesená nebo držená výbava; oblečené články zbroje a oděvu se nezapočítávají podruhé. Za každých celých 20 lb efektivní výbavy = 5 ENC (HMK str. 122).','V Truhlici':'Hmotnost uložených věcí, která aktuálně nezvyšuje zatížení postavy.',
  'ENC zbroje':'Zatížení zbroje vypočítané z ověřených vrstev a dílů; nesprávné vrstvy jsou blokované.',
  'Gear ENC':'Za každých úplných 20 lb efektivní výbavy vzniká 5 ENC. Nepohodlné nesení a batoh upravují efektivní hmotnost podle HMK str. 122.',
  'Upravené ENC':'Výsledné ENC podle zbroje, Gear ENC a Strength Modifieru; vstupuje do pohybu a fyzických testů.',
  'Bulk H / P / T / N':'Bulk podle zbrojních vrstev pro hlavu, paže, trup a nohy; jde o místní postihy, nikoli čtyři další hmotnosti.',
  'Hotovost':'Aktuální doložené denáry po nákupech a potvrzených úpravách.'};
 const currentWater=data.campaignClock?
  waterskinBalances(data.journal,campaignKey(data.campaignClock),c.id,data.campaignClock.minute):[];
 const waterByItem=new Map();
 for(const lot of currentWater)waterByItem.set(lot.itemId,(waterByItem.get(lot.itemId)||0)+lot.remaining);
 const viewRow=r=>{
  const x=r.item,p=x.snapshot?.properties||{};
  const vesselCapacity=waterContainerCapacity(x);
  const waterAmount=vesselCapacity===null?null:(waterByItem.get(x.id)||0);
  const waterStatus=waterAmount===null?'':waterAmount<=0?' (prázdná)':waterAmount>=vesselCapacity?' (plná vody)':` (částečně naplněná: ${waterAmount} gal)`;
  const potionInside=data.campaignClock&&x.sourceItemId===PRINTED_VIAL?
   data.journal.filter(j=>j.calendarCampaignId===campaignKey(data.campaignClock)&&j.calendarHerbVialBinding?.vialId===x.id)
    .map(j=>({j,done:data.journal.find(y=>y.id===j.calendarHerbVialBinding.completeId)?.calendarHerbPotionComplete}))
    .find(({j,done})=>done&&data.campaignClock.minute<done.expiryMinute&&
      !data.journal.some(y=>y.calendarCampaignId===campaignKey(data.campaignClock)&&
        (y.calendarHerbPotionAdminister?.completeId===j.calendarHerbVialBinding.completeId||y.calendarHerbVialDiscard?.completeId===j.calendarHerbVialBinding.completeId)))?.done:null;
  const alchemyInside=data.campaignClock&&x.sourceItemId===PRINTED_VIAL?
   data.journal.filter(j=>j.calendarCampaignId===campaignKey(data.campaignClock)&&j.calendarAlchemyVialBinding?.vialId===x.id)
    .map(j=>({j,state:alchemyVialState(data.journal,campaignKey(data.campaignClock),j.calendarAlchemyVialBinding.finishId,data.campaignClock.minute)}))
    .find(({state})=>state?.full)?.j:null;
  const alchemyStrength=alchemyInside?alchemyElixirStates(data.journal,campaignKey(data.campaignClock)).find(a=>a.finishId===alchemyInside.calendarAlchemyVialBinding.finishId):null;
  const rationLots=availableRationLots(data.journal,campaignKey(data.campaignClock),c.id,data.campaignClock?.minute??0);
  const rationLot=rationLots.find(l=>x.id===l.itemId);
  const staleRationLot=rationStockBalances(data.journal,campaignKey(data.campaignClock),c.id,data.campaignClock?.minute??0).find(l=>x.id===l.itemId&&l.minute<=(data.campaignClock?.minute??0)&&l.remaining>=0.5);
  const extras=r.keyFields.filter(t=>!/^Tištěná položka vybavení HMK, str\. \d+; výběr do počáteční výbavy je orientační, nikoli povinný\.$/i.test(t.trim()));
  const details=extras.length||r.protection.length?`<details class="inv-spec-details"><summary>Parametry (${extras.length+r.protection.length})</summary>${extras.map(t=>`<div>${esc(t)}</div>`).join('')}${r.protection.length?`<div class="inv-av-scroll"><table class="catalog-spec"><thead><tr><th>Lokace</th><th>B</th><th>E</th><th>P</th><th>F</th></tr></thead><tbody>${r.protection.map(y=>`<tr><td>${esc(y.loc)}</td><td>${esc(y.b)}</td><td>${esc(y.e)}</td><td>${esc(y.p)}</td><td>${esc(y.f)}</td></tr>`).join('')}</tbody></table></div>`:''}</details>`:'<span class="muted">Bez dalších katalogových atributů</span>';
  // One row = one underlying source record; all actions target that exact ID.
  // Historical bundles may contain multiple units in one record; preserve their
  // quantity instead of inventing a migration or silently reporting "1 ks".
  const lotNote=r.qty!==null&&r.qty!==1?`<span class="inv-item-kind">${r.qty} kusů v původním záznamu</span>`:'';
  const unitLabel=r.qty!==null&&r.qty!==1?'Celková hmotnost':'Hmotnost';
  return `<tr><th scope="row">${esc(x.snapshot?.name||'Bezejmenný předmět')}${esc(waterStatus)}${lotNote}${potionInside?`<span class="inv-item-kind">Naplněna · ${esc(potionInside.herbType)} (${esc(potencyLabel(potionInside.potency))}); obsah bez doložené hmotnosti</span>`:''}${alchemyInside?`<span class="inv-item-kind">Alchemy · ${esc(alchemyStrength?.elixirName||'elixír')} · AS ${alchemyStrength?.currentAS??'?'}${alchemyStrength?.dispersed?' · obsah vyprázdněn':alchemyStrength?.expires?' · enchantment zanikl':''} · plná 0,5 lb</span>`:''}<span class="inv-item-kind">${esc(x.snapshot?.category||'jiné')}${visibleInventoryNote(x.condition)?' · '+esc(visibleInventoryNote(x.condition)):''}${x.slot==='chest'?' · '+esc(x.chestLocation||'Truhlice'):''}${x.gearStowage==='backpack'?' · v batohu':x.gearStowage==='awkward'?' · nepohodlně neseno':''}${['main_hand','off_hand'].includes(x.slot)&&x.snapshot?.category==='weapon'?' · '+(gripOf(x)==='two'?'obouručně':'jednoručně'):''}</span></th><td>${esc(slotLabel(x.slot))}</td><td class="inv-number">${number(r.wq)}</td><td class="inv-number inv-price">${r.totalPrice!==null?`${r.totalPrice} d`:esc(r.priceLabel.replace(/\s*\/\s*ks\b/gi,'').replace(/\s*d\s*\/\s*12\s*ks\b/gi,' d za 12 kusů'))}</td><td class="inv-number" title="${esc(unitLabel)}">${r.totalWeight===null?'—':`${r.totalWeight.toFixed(1)} lb`}</td><td>${esc(r.armourENC)}</td><td class="inv-key-spec">${details}</td><td><div class="inv-row-actions" data-inv-action-menu>
 <select aria-label="Akce s předmětem ${esc(x.snapshot?.name||'předmět')}" data-inv-action-select>
 <option value="">Vybrat akci…</option>
 ${x._campaignRationReceipt?'':`<option value="edit">Upravit</option>`}
 ${x._campaignRationReceipt?'':`<option value="chest">${x.slot==='chest'?'Vyzvednout':'Do Truhlice'}</option>`}
 ${rationLot?`<option value="ration-transfer" data-source-id="${esc(rationLot.sourceId)}">Předat potraviny</option>`:''}
 ${staleRationLot?`<option value="ration-loss" data-source-id="${esc(staleRationLot.sourceId)}">Odpis potravin</option>`:''}
 ${!x._campaignRationReceipt&&data.characters.length>1?`<option value="transfer">Předat předmět</option>`:''}
 ${!x._campaignRationReceipt?`<option value="remove">Ztráta / vyřadit</option>`:''}
 ${(staleRationLot||(!x._campaignRationReceipt&&x.slot!=='chest'&&data.campaignClock&&currentWater.some(l=>l.itemId===x.id&&l.remaining>=0.5)))?`<option value="partial">Odložit část zásob</option>`:''}
 </select><button type="button" class="secondary" data-inv-action-confirm data-inv-item-id="${esc(x.id)}">OK</button></div></td></tr>`;
 };
 const table=(list,title)=>`<h4>${title} · ${czCount(list.length,'záznam','záznamy','záznamů')}</h4>${list.length?`<div class="inv-table-scroll"><table class="catalog-spec inv-ledger-table"><colgroup><col style="width:22%"><col style="width:12%"><col style="width:6%"><col style="width:12%"><col style="width:9%"><col style="width:8%"><col style="width:13%"><col style="width:18%"></colgroup><thead><tr><th>Předmět</th><th>Umístění</th><th>WQ</th><th>Cena</th><th>Hmotnost</th><th>ENC zbroje</th><th>Vlastnosti / účinky</th><th>Akce</th></tr></thead><tbody>${list.map(viewRow).join('')}</tbody></table></div>`:'<p class="muted">Žádné položky.</p>'}`;
 return `<div class="inv-summary-grid">${cards.map(([name,value])=>`<div class="inv-summary-stat" data-hmk-help="${esc(invHelp[name]||name)}" tabindex="0" aria-label="${esc(name+': '+(invHelp[name]||name))}"><span>${esc(name)}</span><strong>${esc(value)}</strong></div>`).join('')}</div><p class="tiny muted">Hmotnost majetku zahrnuje také oblečené části oděvu/zbroje; Gear ENC počítá jen nesenou a drženou výbavu. ENC výbavy se odvozuje z celkové efektivní hmotnosti a způsobu nesení. Nelze ho přidělovat každému předmětu zvlášť. Jednotkové ceny a váhy chybějících katalogových údajů nejsou odhadovány.</p>${table(rows.filter(r=>r.kind==='equipped'),'Nasazené a držené předměty')}${table(rows.filter(r=>r.kind==='carried'),'Nesené předměty')}${table(rows.filter(r=>r.kind==='chest'),'Truhlice · věci ponechané doma / v úschově')}<p class="tiny muted">Truhlice je místo uložení, nikoli nový předmět ani pravidlový bonus. Zůstává vlastníkem postavy, ale uložené věci nejsou dostupné na cestě a nezapočítávají se do ENC. Každé vyzvednutí nebo uložení vyžaduje potvrzenou fyzickou dostupnost u GM a nemění čas kampaně.</p><div class="inv-footer-totals"><strong>Celkem ${czCount(sourceRows.reduce((n,r)=>n+(r.qty||0),0),'kus','kusy','kusů')} v ${czCount(rows.length,'inventárním záznamu','inventárních záznamech','inventárních záznamech')}</strong><span>Známá hodnota: ${totals.knownValue} d${totals.unknownValue?` (${totals.unknownValue} bez ceny)`:''}</span><span>Známá hmotnost: ${totals.knownWeightLb.toFixed(1)} lb${totals.unknownWeight?` (${totals.unknownWeight} bez hmotnosti)`:''}</span><span>Gear ENC: ${number(load.gearENC)} · Armour ENC: ${number(load.armourENC)}${Number.isFinite(load.knownArmourENC)&&!Number.isFinite(load.armourENC)?` (známé od ${load.knownArmourENC}${Number.isFinite(load.armourENCUpperBound)&&load.armourENCUpperBound!==load.knownArmourENC?' do '+load.armourENCUpperBound:''})`: ''} · Bulk: ${load.bulkReady?number(load.meleeBulkPenalty):load.prohibitedOutfit?'zakázaná sestava':'pořadí neurčeno'}</span></div>`;
}
function inventoryPartialDropForm(x){
 const clock=data.campaignClock,actorId=x?.characterId;
 if(!clock||!x||x.slot==='chest')return '';
 const key=campaignKey(clock),minute=clock.minute;
 const food=rationStockBalances(data.journal,key,actorId,minute)
  .filter(l=>l.itemId===x.id&&l.minute<=minute&&l.remaining>=0.5)
  .map(l=>({kind:'food',sourceId:l.sourceId,remaining:l.remaining,label:`${l.name||x.snapshot?.name||'Potrava'} · ${l.remaining} dávky` }));
 const water=waterskinBalances(data.journal,key,actorId,minute)
  .filter(l=>l.itemId===x.id&&l.remaining>=0.5)
  .map((l,i)=>({kind:'water',sourceId:l.fillId,remaining:l.remaining,label:`Naplnění ${i+1} · ${l.remaining} gal`}));
 const lots=[...food,...water];
 if(!lots.length)return '';
 return `<div class="editor-backdrop"><section class="panel editor-dialog" role="dialog" aria-modal="true" aria-labelledby="partial-drop-title"><h2 id="partial-drop-title">Odložit část · ${esc(x.snapshot?.name||'zásoby')}</h2><p class="tiny muted">Skutečný odpis se zapíše do původních dokladů jídla nebo vody, upraví nesenou hmotnost. Není to vypití ani přemístění do Truhlice.</p><form id="inventory-partial-drop-form"><input name="actorId" type="hidden" value="${esc(actorId)}"><input name="itemId" type="hidden" value="${esc(x.id)}"><label>Doložená zásoba<select name="sourceId" data-inv-partial-lot required>${lots.map(l=>`<option value="${esc(l.sourceId)}" data-kind="${l.kind}" data-remaining="${l.remaining}">${esc(l.label)}</option>`).join('')}</select></label><label>Odložit množství<input name="quantity" type="number" min="0.5" max="${lots[0].remaining}" step="0.5" value="0.5" required data-inv-partial-quantity></label><label>Důvod skutečného odložení<input name="reason" minlength="2" maxlength="160" required placeholder="Např. poškozené zásoby, vylitá voda"></label><div class="actions"><button type="submit">Zapsat odložení</button><button type="button" class="secondary" data-action="cancel-editor">Zrušit</button></div></form></section></div>`;
}
function physicalWaterPanel(actor){
 const clock=data.campaignClock;const key=campaignKey(clock);
 const owned=data.inventory.filter(x=>x.characterId===actor.id&&waterContainerCapacity(x)!==null&&x.slot==='carried');
 const rows=owned.map(x=>({item:x,volume:waterskinBalances(data.journal,key,actor.id).filter(y=>y.itemId===x.id).reduce((n,y)=>n+y.remaining,0)}));
 return `<section class="folio-water-ledger" aria-label="Fyzická voda"><h4>Voda v nádobách</h4> ${rows.length?`<div class="inv-table-scroll"><table class="catalog-spec"><thead><tr><th>Nádoba</th><th>Voda</th><th>Váha: nádoba + voda</th><th>Akce</th></tr></thead><tbody>${rows.map(({item:x,volume})=>`<tr><td>${esc(x.snapshot.name)}</td><td>${volume} / ${waterContainerCapacity(x)} gal</td><td>${Number.isFinite(x.snapshot?.properties?.weightLb)?`${x.snapshot.properties.weightLb.toFixed(1)} + ${(volume*10).toFixed(1)} = ${(x.snapshot.properties.weightLb+volume*10).toFixed(1)} lb`:'Váha nádoby není doložena'}</td><td>${volume===0?`<button type="button" class="secondary" data-fill-water="${esc(x.id)}" ${clock?'':'disabled'}>Potvrdit naplnění</button>` :`Naplněna · <button type="button" class="secondary" data-pour-water="${esc(x.id)}" ${clock?'':'disabled'}>Předat vodu</button> <button type="button" class="danger" data-loss-water="${esc(x.id)}" ${clock?'':'disabled'}>Odpis vody</button>`}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted tiny">Žádný ověřený nesený Waterskin, 2 quart nebo Jug, 1 gallon. Každou nádobu evidujte samostatně jako jeden kus.</p>'}
 </section>`;
}
function armourLoadoutPanel(inv,owner=null){
 const report=auditArmourLoadout(inv);
 const load=owner?resolveCombatantLoad({character:owner,inventory:activeRationInventory()}):null;
 const reorderPreview=load&&!load.bulkReady&&load.layeringFeasibility?.status!=='forbidden'?previewExistingArmourArrangement(inv):null;
 const rows=layerDisplayRows(report,inv,load).map(r=>`<tr class="arm-layer-row arm-layer-${r.status}"><th scope="row" title="${esc(r.names)}">${esc(r.location)} <span class="muted tiny">${esc(JOURNAL_ANATOMICAL_LOCATIONS.find(([code])=>code===r.location)?.[1]||r.locationName)}</span></th><td class="arm-layer-count ${r.status==='valid'?'':'arm-layer-alert'}" title="${esc(r.detail)}">${r.count}${r.status==='over-limit'?` <b>+${r.count-5}</b>`:''}</td><td>${r.protection.b}</td><td>${r.protection.e}</td><td>${r.protection.p}</td><td>${r.protection.f}</td><td class="arm-layer-explain">${r.status==='valid'?'—':esc(r.detail)}</td></tr>`).join('');
 return `<section class="panel wide"><h3>Worn Armour · Location Protection & Layers</h3><div class="hmk-outfit-toolbar" role="group" aria-label="Hromadné oblékání a svlékání"><button type="button" data-outfit-action="armour" ${!owner||combatInitiativeSequence?'disabled':''} title="Najít nejvyšší ověřenou ochranu B/E/P/F a poté rigiditu mezi vlastněnými články HMK. Respektuje legální vrstvení.">Obléknout nejlepší zbroj / kompletní set</button><button type="button" class="secondary" data-outfit-action="clothing" ${!owner||combatInitiativeSequence?'disabled':''} title="Sestavit nejlepší legální kombinaci látkových článků HMK. Ostatní zbroj se svlékne.">Obléknout běžný oděv</button><button type="button" class="secondary" data-outfit-action="undress" ${!owner||combatInitiativeSequence?'disabled':''} title="Svléknout všechny aktuálně oblečené články zbroje a látkového oděvu; přesunou se do nesené výbavy.">Svléknout</button></div><p class="tiny muted">Zbroj: u přesného zakoupeného kompletu se použije tištěná sestava a její ověřené hodnoty, bez umělého limitu 12 článků. U ostatních kombinací maximum součtu doložených B/E/P/F, poté rigidních lokací, následně nejmenší Bulk/ENC a hmotnost. Běžný oděv: látkové články a kožená obuv podle HMK s. 118; jiné textilie bez doložené anatomie se automaticky neoblékají. Před změnou se zobrazí kontrolovaný návrh. Během Initiative je změna zakázána.</p><p class="muted tiny">Zobrazené B/E/P/F jsou součty z předmětů, nikoli automatické potvrzení pravidlové ochrany. Červeně je prokázané překročení počtu vrstev či nepřípustná materiálová kombinace, jantarově neznámé fyzické pořadí.</p>${rows?`<div class="catalog-scroll"><table class="catalog-spec arm-layer-table"><thead><tr><th>Location</th><th>Layers</th><th>${journalTerm('b')}</th><th>${journalTerm('e')}</th><th>${journalTerm('p')}</th><th>${journalTerm('f')}</th><th>Kontrola</th></tr></thead><tbody>${rows}</tbody></table></div>`:'<p>Žádná nasazená zbroj.</p>'}${reorderPreview?.ready?`<div class="actions"><button type="button" class="secondary" data-armour-autolayer="${esc(owner.id)}">Uspořádat zbroj do přípustných vrstev</button><p class="tiny muted">Aplikace navrhne a zapíše doložené pořadí, nikoli nová pravidla ani nový postih. Nemění počet či vlastnictví předmětů.</p></div>`:''}${report.skipped.length?`<p class="notice">U ${report.skipped.length} položek chybí úplná anatomická data; ochrana je jen částečný součet.</p>`:''}</section>`;
}
function combatantLoadPanel(c){
 const r=resolveCombatantLoad({character:c,inventory:activeRationInventory()});
 const fmt=n=>Number.isFinite(n)?String(n):'—';
 const info=r.encReady?`<strong>Upravené ENC ${fmt(r.modifiedENC)}</strong> · Zbroj ${fmt(r.armourENC)} + nesená výbava ${fmt(r.gearENC)}; STR ${fmt(r.str)} (${r.strengthModifier>=0?'+':''}${fmt(r.strengthModifier)}); PF / období ${fmt(r.personalFatiguePerPeriod)}.`:
  Number.isFinite(r.knownMinimumENC)?`<strong>${r.prohibitedOutfit?'Aritmetické zatížení nepřípustné sestavy':'Známý rozsah upraveného ENC'}: ${fmt(r.knownMinimumENC)}${Number.isFinite(r.knownMaximumENC)&&r.knownMaximumENC!==r.knownMinimumENC?' až '+fmt(r.knownMaximumENC):''}</strong> (zbroj ${fmt(r.knownArmourENC)}${Number.isFinite(r.armourENCUpperBound)&&r.armourENCUpperBound!==r.knownArmourENC?' až '+fmt(r.armourENCUpperBound):''}, výbava ${fmt(r.gearENC)}). ${r.prohibitedOutfit?'Kombinace se podle HMK nesmí nosit; zobrazený součet ji nelegalizuje.':'Pokud není zakresleno pořadí, možné dodatečné ENC za vnější D/Q je uvedeno rozpětím.'}`:
  'ENC nelze úplně spočítat: některému kusu chybí ověřené parametry.';
 const bulk=r.bulkReady?`Bulk podle tělesných zón Hlava / Paže / Trup / Nohy: ${['head','arms','torso','legs'].map(z=>fmt(r.bulkByZone[z])).join(' / ')}.`:
  r.prohibitedOutfit?'Bulk nelze stanovit: sestava je podle HMK nepřípustná, nepoužije se smyšlený náhradní postih.':
  'Bulk není doložen: chybí skutečné pořadí více vrstev. Možné uspořádání se zobrazuje přímo u lokací.';
 const readable=readableLayerIssues(r,data.inventory.filter(x=>x.characterId===c.id));
 return `<section class="panel wide"><h3>HMK · zatížení postavy (str. 112, 117, 122)</h3><p>${info}</p><p class="tiny">${bulk} ENC a Bulk jsou oddělené veličiny. Postihy se do Skill Tests započtou pouze při úplném pravidlovém výpočtu. Neexistuje univerzální postih za zakázanou kovovou kombinaci.</p>${readable.length?`<div class="armour-friendly-warnings">${readable.map(x=>`<p class="notice">${esc(x)}</p>`).join('')}</div>`:''}</section>`;
}
/** Display the SAME active Combat mandatory form on Character Sheet, without
 * inventing a new writer or independent combat clock. Other participants'
 * obligations remain first; expired/unsupported events cannot be acted on. */
function sheetMandatoryBridge(c){
 if(!encounterSelection.has(c.id))return '';
 const roster=selectedEncounterCharacters(),first=firstGuidedMandatoryDue(roster);
 if(!first)return '';
 const live=combatInitiativeSequence?liveInitiativeSequence():null;
 const actorId=live?currentEncounterActor(live):combatClock.actorId;
 const other=character(first.characterId);
 const header=`<h3>HMK · povinný následný krok Combat</h3><p class="tiny muted">Jedna autoritativní časová osa a Combat State. Bez druhého hodu nebo zápisu.</p>`;
 if(first.characterId!==c.id)return `<section class="panel wide hmk-skill-mandatory-bridge">${header}<p class="notice">Dříve je nutné dokončit následek postavy ${esc(other?.name??first.characterId)} (${esc(first.type)}). Pořadí určuje Initiative.</p><button type="button" class="secondary" data-nav="encounter">Přejít do Combat</button></section>`;
 const bridge=verifyMandatoryHandoff({state:persistentStateOf(c),characterId:c.id,round:combatClock.round,actorId,
  turnEnded:first.turnEnded,timelineId:combatInjuryTimelineId,firstDue:first});
 if(!bridge.ready)return `<section class="panel wide hmk-skill-mandatory-bridge">${header}<p class="notice">${esc(bridge.reason)}</p><button type="button" class="secondary" data-nav="encounter">Přejít k příslušnému Combat kroku</button></section>`;
 return `<section class="panel wide hmk-skill-mandatory-bridge">${header}${guidedMandatoryPanel(roster)}</section>`;
}
function liveSpecialEffectsPanel(c){
 const now=data.campaignClock?.minute,live=activeSpecialEffects(c,now);
 const all=c.hmk?.liveEffects;
 if(!all)return '';
 const rows=[];
 if(live.festival)rows.push('Renewed Faith: +1 maximum Piety · do '+displayCampaignMinute(live.festival.until));
 if(live.blessing)rows.push('Ceremony: Blessing +'+live.blessing.bonus+' · '+live.blessing.subjects.join(', ')+' · do '+displayCampaignMinute(live.blessing.until));
 if(live.maxPiety!==null)rows.push('Aktuální maximum Piety: '+live.maxPiety+' (dle aktivního Festivalu a Morality)');
 if(live.currentPiety!==null)rows.push('Aktuální Piety: '+live.currentPiety+' (omezeno aktuálním maximem)');
 for(const rite of live.rites)rows.push('Shamanic Rite · do '+displayCampaignMinute(rite.until));
 for(const t of projectTalismanStatus({recipient:c,inventory:data.inventory,minute:now}))rows.push('Talisman '+t.family+' / '+t.subject+' · '+t.reason+' · do '+displayCampaignMinute(t.until));
 for(const lock of all.talismanLockouts||[])if(now!=null&&now<lock.until)rows.push('Talisman Bestowal: zákaz dalšího pokusu do '+displayCampaignMinute(lock.until)+' (Trance F).');
 if(live.lostSpiritPowers.length)rows.push('Ztracené uložené Spirit Powers (indexy): '+live.lostSpiritPowers.join(', '));
 if(now==null)rows.push('K zobrazení platnosti časovaných účinků je nutný kalendář kampaně.');
 if(!rows.length)rows.push('Žádný aktivní časovaný účinek (starší účinky mohou být již prošlé).');
 return '<section class="panel wide"><h3>Trvalé účinky z potvrzených SR</h3><p class="tiny muted">Časované účinky se po uplynutí lhůty automaticky přestanou uplatňovat; původní důkazy zůstanou zachované.</p>'+rows.map(x=>'<p>'+esc(x)+'</p>').join('')+'</section>';
}
