function decorateTrekkingRoutineUI(root){
 const host=root.querySelector('.hc-trek-routine');if(!host)return;
 const form=host.querySelector('#campaign-trekking-context-form');if(!form)return;
 for(const label of form.querySelectorAll('label')){
  const control=label.querySelector('input[name],select[name],textarea[name]');
  const help=TREKKING_FIELD_HELP[control?.name];
  if(!help)continue;
  label.setAttribute('data-hmk-help',help);
  label.tabIndex=0;
 }
 for(const legend of form.querySelectorAll('legend')){
  const help=TREKKING_SECTION_HELP[legend.textContent.trim()]||'V této části vyplňte pouze skutečně doložené podklady konkrétní cestovní hlídky.';
  legend.setAttribute('data-hmk-help',help);
  legend.tabIndex=0;
 }
 for(const summary of host.querySelectorAll('summary')){
  summary.setAttribute('data-hmk-help',summary.closest('.hmk-trek-guide')?'Pořadí kroků od přípravy trasy až po dokončení hlídky, zdravotní dopady a zápisy v kalendáři.':'Otevře formulář podkladů pro jednu cestovní hlídku; nijak neposouvá čas ani neuděluje zdravotní následky.');
 }
 for(const item of host.querySelectorAll('.hmk-trek-steps li')){
  item.setAttribute('data-hmk-help',item.textContent.trim());item.tabIndex=0;
 }
 const submit=form.querySelector('button[type="submit"]');
 if(submit)submit.setAttribute('data-hmk-help','Zaznamená pravidlové podklady jedné hlídky do historie a kalendáře, ale neprovede posun času, END testy ani automatické zranění. Na následné povinnosti navazují samostatní průvodci.');
 host.querySelector('h3')?.setAttribute('data-hmk-help','Trekking Routine spojuje pravidla počasí, orientace, pohybu a nebezpečí. Příprava hlídky, skutečné hody, posun času a zdravotní následky jsou oddělené navazující kroky (HMK s. 141–150).');
}
// Visible identifiers are presentation data, never authoritative storage keys.
// Work only on rendered text (not input values, textarea contents, data-* or option values).
function hideVisibleTechnicalUUIDs(root){
 const chars=new Map((data?.characters??[]).filter(c=>typeof c?.id==='string').map(c=>[c.id.toLowerCase(),c.name||'Nepojmenovaná postava']));
 const uuid=/\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b/gi;
 const clean=t=>{
  if(!uuid.test(t))return t;
  uuid.lastIndex=0;
  const ids=[...new Set([...t.matchAll(uuid)].map(m=>m[0]))];
  let value=t;
  for(const id of ids){
   const literal=id.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
   const name=chars.get(id.toLowerCase());
   if(name){
    // The old UI often appended a character's raw UUID after a visible name.
    value=value.replace(new RegExp('\\s*[·–—]\\s*'+literal+'\\b','gi'),'');
    value=value.replace(new RegExp('\\b'+literal+'\\s*\\(([^)]*)\\)','gi'),(_m,inside)=>inside);
    value=value.replace(new RegExp('\\b'+literal+'\\b','gi'),name);
   }else value=value.replace(new RegExp('\\b'+literal+'\\b','gi'),'interní záznam');
  }
  return value;
 };
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];
 while(walker.nextNode())nodes.push(walker.currentNode);
 for(const node of nodes){
  if(node.parentElement?.closest('script,style,textarea,[contenteditable="true"]'))continue;
  const next=clean(node.nodeValue);if(next!==node.nodeValue)node.nodeValue=next;
 }
 for(const el of root.querySelectorAll('[title],[aria-label],[data-hmk-help],[aria-description],[alt]')){
  for(const key of ['title','aria-label','data-hmk-help','aria-description','alt']){const orig=el.getAttribute(key);if(orig){const next=clean(orig);if(next!==orig)el.setAttribute(key,next);}}
 }
}
function render(){
 // Deny all paths to partially generated sheets, even routes that set view
 // directly without clicking a registry card (import, skill link, wizard exit).
 if(view==='sheet'){
  const c=character(selected),gate=characterJournalReadiness(c);
  if(!gate.ready){
   activeSheetSection='overview';sheetEditingId=null;overlay=null;
   view=c?.hmk?.creation?'creation':'characters';
   notice=gate.reason+' Dokončete pravidlovou tvorbu a její závěrečnou revizi.';
  }
 }
 if(view==='sheet'&&isCharacterSpecialtySection(activeSheetSection)&&!characterSpecialtyById(character(selected),activeSheetSection))activeSheetSection='overview';
 // The sidebar has its own scrolling container. Rendering replaces its DOM node,
 // so retain the actual scroll position instead of resetting the menu to the top.
 const app=document.getElementById('app');
 const sidebarPosition=app.querySelector('.layout>.nav')?.scrollTop??0;
 const nextRoute=currentUiRoute();
 if(!uiNavigationRestoring)uiNavigation.visit(nextRoute,{scrollY:window.scrollY});
 writeGuidedDraft();
 app.innerHTML=main()+(overlay||'');
 hideVisibleTechnicalUUIDs(app);
 decorateTrekkingRoutineUI(app);
 const sidebar=app.querySelector('.layout>.nav');
 if(sidebar)sidebar.scrollTop=sidebarPosition;
 refreshAllCalendarHealingFields();
 enhanceHMKDiceFields();
 updateExpeditionDiceFields(app.querySelector('#campaign-expedition-form'),{reset:false});
}
// On narrow layouts the navigation joins the page scroll instead of using
// its own scroll container. Keep the viewport at the same position on sidebar
// clicks, rather than allowing focus/scroll anchoring to jump to page top.
document.addEventListener('click',e=>{
 if(!e.target.closest?.('.nav button'))return;
 const previousY=window.scrollY;
 requestAnimationFrame(()=>{
  if(Math.abs(window.scrollY-previousY)>1){
   window.scrollTo({top:previousY,behavior:'instant'});
  }
 });
},true);
function ask(msg){return window.confirm(msg)}
// HMK p.187: independent Fear/Aberrance form, ONE existing full-record CAS.
document.addEventListener('submit',event=>{
 const form=event.target;
 if(!['hmk-fear-exposure-form','hmk-fear-safe-form','hmk-fear-reaction-form'].includes(form?.id))return;
 event.preventDefault();event.stopImmediatePropagation();
 if(storageReadOnly){alert('Úložiště je v read-only stavu. Žádný fyzický hod neopakujte.');return}
 const v=Object.fromEntries(new FormData(form));
 try{
  const args={document:data,characterId:v.characterId,eventId:uuid(),storage:cloudStorage,
   key:STORAGE,baseline:storageBaseline,gmConfirmed:v.gmConfirmed==='on'};
  let result;
  if(form.id==='hmk-fear-exposure-form')result=persistFearExposure({...args,
   sourceKind:v.sourceKind,sourceId:v.sourceKind==='character'?v.sourceCharacter:v.sourceId,
   sourceDescription:v.sourceDescription,aberrance:Number(v.aberrance),d100:Number(v.d100),
   gmConfirmedSource:v.gmConfirmedSource==='on'});
  else if(form.id==='hmk-fear-safe-form')result=persistFearSafeRecovery({...args,
   elapsedMinutes:Number(v.elapsedMinutes),safeFromSource:v.safeFromSource==='on',outOfLOS:v.outOfLOS==='on'});
  else result=persistFearEndTurnReaction({...args,d100:Number(v.d100)});
  if(!result.ok){if(result.readOnly)storageReadOnly=true;
   alert('Fear nebyl bezpečně zapsán: '+result.code);render();return}
  data=result.document;storageBaseline=result.serialized;
  mirrorInitiative(validateEncounterSequence(data.combatRuntime.sequence),data.combatRuntime.clock);
  notice='Fear / Aberrance: fyzický výsledek a následky jsou uloženy jedním kontrolním bodem.';
  render();
 }catch(error){alert('Fear / Aberrance — bez zápisu: '+error.message)}
},true);
