// Rule-derived Creation values cannot be silently overwritten outside their 14-step proof trail.
document.addEventListener('click',e=>{
 const start=e.target.closest('[data-sheet-edit]'),cancel=e.target.closest('[data-sheet-cancel]');
 if(!start&&!cancel)return;
 e.preventDefault();e.stopImmediatePropagation();
 if(start){if(combatInitiativeSequence)return alert('Během aktivní Initiative nelze upravovat Character Sheet.');if(!selected||!character(selected))return;sheetEditingId=selected;activeSheetSection='overview';}
 else {sheetEditingId=null;activeSheetSection='overview';}
 render();
},true);
document.addEventListener('submit',e=>{
 const form=e.target;if(form.id!=='sheet-inline-form')return;
 e.preventDefault();e.stopImmediatePropagation();
 const c=character(selected);if(!c||sheetEditingId!==c.id)return;
 if(combatInitiativeSequence)return alert('Během aktivní Initiative nelze měnit Character Sheet.');
 const v=Object.fromEntries(new FormData(form));
 const revisedName=String(v.sheet_character_name??c.name).trim();
 if(!revisedName||revisedName.length>120){return alert('Jméno postavy: zadejte 1–120 znaků.');}
 const attrKeys=['str','end','dex','agl','per','cml','aur','wil','rea','cre','emp','elo'];
 const valid=(raw,label,max)=>{if(!/^(?:0|[1-9][0-9]*)$/.test(String(raw??''))||!Number.isSafeInteger(Number(raw))||Number(raw)>max)throw Error(label+': zadejte celé nezáporné číslo.');return Number(raw)};
 let attrs=[],dp=[],legacy=[],coinChange=null;
 try{
  for(const key of attrKeys){
   const raw=v['sheet_attr_'+key];
   attrs.push([key,valid(raw,key,99)]);
  }
  if(isCreationOwned(c)){
   const original=calculateSheetSkills(c);
   const stages=['Folk Skills','Arcane Talent Skills','Family Skills','Background Skills','Occupation Skills','Optional Skills','Veteran Skills','Sunsign Skills','Native Language / Religion','GM Bonus Languages'];
   for(const skill of original){
    if(skill.subskillOf||skill.perceptionParent)continue;
    for(const stage of stages){
     const name='sheet_dp_'+encodeURIComponent(skill.name)+'_'+encodeURIComponent(stage);
     if(!(name in v))throw Error('Chybí editační DP pole: '+skill.name+' / '+stage);
     dp.push([skill.name,stage,valid(v[name],skill.name+' / '+stage,100)]);
    }
   }
  }else{
   for(let i=0;i<(c.hmk?.skills??[]).length;i++){
    if(!('sheet_legacy_ml_'+i in v))continue;
    legacy.push([i,valid(v['sheet_legacy_ml_'+i],'Skill ML',200)]);
   }
  }
  const cash=cashForCharacter(c);
  if('sheet_coin_current' in v){
   if(!cash.ok)throw Error('Aktuální hotovost nelze upravit: '+cash.reason);
   coinChange=valid(v.sheet_coin_current,'Aktuální mince',999999999)-cash.balance;
  }
 }catch(err){return alert(err.message)}
 const ok=mutate(()=>{
  const live=character(selected);if(!live||live.id!==c.id)throw Error('Postava se změnila');
  // Rename is a presentation/identity edit, never a change of the 14-step
  // creation proofs, dice or the completed status.
  live.name=revisedName;
  const h=live.hmk??(live.hmk={});h.attributes??={};
  if(isCreationOwned(live)){
   h.advancement??={};h.advancement.attributes??={};h.advancement.skillDP??={};
   for(const [key,n] of attrs){
    const original=live.hmk.creation?.attributeProof?.[key]?.score;
    if(!Number.isSafeInteger(original))throw Error('Chybí původní atributový hod '+key);
    if(n===original)delete h.advancement.attributes[key];else h.advancement.attributes[key]=n;
    h.attributes[key]=n;
   }
   // Persist only changes relative to the previous effective ledger. The
   // original DP allocations / dice proofs stay untouched in creation.
   const baseline=calculateSheetSkills({...live,hmk:{...h,advancement:{...h.advancement,skillDP:{}}}});
   const baselineMap=new Map(baseline.map(x=>[x.name,x]));
   for(const [skill,stage,n] of dp){
    const initial=baselineMap.get(skill)?.dp.find(x=>x.stage===stage)?.dp??0;
    const existing=h.advancement.skillDP[skill]??{};
    if(n===initial)delete existing[stage];else existing[stage]=n;
    if(Object.keys(existing).length)h.advancement.skillDP[skill]=existing;
    else delete h.advancement.skillDP[skill];
   }
   syncCreationSkills(h,uuid);
  }else{
   for(const [key,n] of attrs)h.attributes[key]=n;
   for(const [i,n] of legacy)h.skills[i].ml=n;
  }
  if(coinChange){
   const reason=String(v.sheet_coin_reason||'').trim();
   if(reason.length<5)throw Error('Při změně hotovosti zadejte skutečný důvod (min. 5 znaků).');
   const key=activeCampaignCashKey(live);
   if(key===null&&Object.keys(live.hmk?.campaignCashAccounts??{}).length)throw Error('Zvolte konkrétní kampaň. Historické neznačené peníze už nelze měnit.');
   if(key===undefined)throw Error('Postava není účastníkem aktuálního kalendáře.');
   if(key!==null)recordCampaignCoinAdjustment(live,{campaignId:key,minute:data.campaignClock.minute,id:uuid(),at:stamp(),deltaPence:coinChange,reason});
   else{h.coinAdjustments??=[];h.coinAdjustments.push({kind:'gm-coin-adjustment',id:uuid(),at:stamp(),deltaPence:coinChange,reason});}
  }
  if(!cashForCharacter(live).ok&&coinChange!==null)throw Error('Nová hotovost nesouhlasí s účetní historií.');
 });
 if(ok){sheetEditingId=null;render();}
},true);

document.addEventListener('submit',e=>{const f=e.target;if(!['character-editor','item-editor','character-form','add-inventory','journal-form'].includes(f.id))return;e.preventDefault();const v=Object.fromEntries(new FormData(f));if(f.id==='character-editor'){if(!v.name.trim())return alert('Zadejte jméno');if(mutate(()=>data.characters.push({id:uuid(),name:v.name.trim(),occupation:v.occupation||'',kind:v.kind,description:v.description||'',portrait:''}))) {overlay=null;render()}return}if(f.id==='character-form'){if(combatInitiativeSequence&&encounterSelection.has(selected))return alert('Identitu aktivního účastníka během Initiative nelze měnit mimo Combat průvodce.');if(!v.name.trim())return alert('Zadejte jméno');mutate(()=>{const live=character(selected);Object.assign(live,{name:v.name.trim(),kind:v.kind,description:v.description,portrait:v.portrait});if(!isCreationOwned(live))live.occupation=v.occupation;});return}if(f.id==='item-editor'){if(editItem&&item(editItem)?.builtin)return alert('Vestavěné definice nelze upravit.');if(!v.name.trim())return alert('Zadejte název');let properties;try{properties=JSON.parse(v.properties||'{}');if(!properties||Array.isArray(properties)||typeof properties!=='object')throw Error()}catch{return alert('Parametry musí být platný JSON objekt')}if(mutate(()=>{const record={id:editItem||uuid(),name:v.name.trim(),category:v.category,description:v.description||'',source:v.source||'',properties};if(editItem)Object.assign(item(editItem),record);else data.items.push(record)})){overlay=null;render()}return}if(f.id==='add-inventory'){if(combatInitiativeSequence)return alert('Během Initiative měňte inventář pouze pravidlově dokončenou akcí Combat průvodce.');const i=item(v.itemId);const quantity=Number(v.quantity);if(!i||!Number.isSafeInteger(quantity)||quantity<1||quantity>999999)return alert('Vyberte předmět a platný počet');if(!validSlotForCategory(v.slot,i.category))return alert('Tento slot neodpovídá kategorii předmětu');if(['main_hand','off_hand','worn'].includes(v.slot)&&quantity!==1)return alert('Vybavený předmět musí představovat jeden kus. Další kusy evidujte samostatně jako nesené.');if(!handSlotAvailable(selected,v.slot))return alert('Ruka je již obsazena. Nejprve přesuňte stávající předmět.');const baseQuality=i.properties?.quality;
 const givenWQ=String(v.currentWQ??'').trim();
 if(givenWQ!==''&&!/^(?:0|[1-9]\d*)$/.test(givenWQ))return alert('Aktuální WQ musí být celé nezáporné číslo 0–999.');
 const requestedWQ=givenWQ===''?null:Number(givenWQ);
 if(givenWQ!==''&&(!Number.isSafeInteger(requestedWQ)||requestedWQ>999))return alert('Aktuální WQ musí být celé číslo 0–999.');
 const currentWQ=givenWQ!==''?requestedWQ:(Number.isSafeInteger(baseQuality)&&baseQuality>=0&&baseQuality<=999?baseQuality:null);
 const nextItem={id:uuid(),currentWQ,characterId:selected,sourceItemId:i.id,snapshot:structuredClone(i),quantity,condition:v.condition||'',slot:v.slot||'carried'};try{if(['main_hand','off_hand'].includes(v.slot)){if(!isHandheldItem(nextItem))throw Error('Tento předmět nelze držet v ruce');validateHandInventory([...data.inventory,nextItem],selected);}}catch(err){return alert(err.message)}mutate(()=>data.inventory.push(nextItem));return}if(f.id==='journal-form'){if(!v.title.trim()&&!v.body.trim())return;mutate(()=>data.journal.push({id:uuid(),characterId:selected,title:v.title.trim()||'Bez názvu',body:v.body,createdAt:stamp()}))}});
document.addEventListener('click',e=>{
 const tab=e.target.closest('[data-library-tab]');
 if(tab){e.preventDefault();libraryTab=tab.dataset.libraryTab;libraryPage=0;query='';render();return}
 const page=e.target.closest('[data-library-page]');
 if(page){e.preventDefault();libraryPage=Math.max(0,Number(page.dataset.libraryPage)||0);render();return}
});
document.addEventListener('submit',e=>{
 const f=e.target.closest('form[data-library-form]');if(!f)return;
 e.preventDefault();e.stopImmediatePropagation();
 if(combatInitiativeSequence)return alert('Během aktivní Initiative nelze vybavení přidávat mimo pravidlový Combat průvodce.');
 const v=Object.fromEntries(new FormData(f));
 const acquisition=e.submitter?.value;
 if(!['buy','free'].includes(acquisition))return alert('Vyberte Koupit nebo Vzít zdarma.');
 const receiver=character(v.recipientId);
 if(!receiver)return alert('Vyberte existující aktivní postavu.');
 if(activeCampaignCashKey(receiver)===undefined)return alert('Postava musí být účastníkem právě aktivní kampaně.');
 libraryRecipientId=receiver.id;
 let sources=[],totalPrice=null,suitName=null,buyQuantity=1;
 if(f.dataset.libraryForm==='suit'){
  const suit=PRINTED_ARMOUR_SUITS_P113_116.find(s=>s.name===v.itemId);
  if(!suit)return alert('Komplet nebyl nalezen.');
  const result=resolveSuitCatalogParts(suit,reconcileSuitArticles(),PRINTED_ARMOUR_ARTICLES_P118,allCatalogItems());
  if(!result.ok)return alert('Sestavu nelze přiřadit: '+result.reason);
  sources=result.parts;totalPrice=suitPurchasePrice(suit);suitName=suit.name;
 }else if(f.dataset.libraryForm==='item'){
  const i=item(v.itemId);if(!i)return alert('Položka již není v knihovně.');
  sources=[i];const offer=libraryPurchaseOffer(i);totalPrice=offer?.pricePence??null;buyQuantity=offer?.quantity??1;
 }else return alert('Neznámý typ položky knihovny.');
 if(acquisition==='buy'){
  try{if(activeCampaignCashKey(receiver)===undefined)throw Error('Postava není členem aktuální kampaně.');prepareLibraryPurchase(receiver,totalPrice,activeCampaignCashKey(receiver))}catch(err){return alert('Nákup odmítnut: '+err.message)}
  if(!ask(`Koupit ${suitName||sources[0]?.name}${buyQuantity>1?' ('+buyQuantity+' ks)':''} za ${totalPrice}d pro postavu ${receiver.name}?`))return;
 }
 const transactionId=uuid(),at=stamp();
 const saved=mutate(()=>{
  if(combatInitiativeSequence)throw Error('Zahájena Initiative.');
  const current=character(receiver.id);if(!current)throw Error('Postava již neexistuje.');
  if(activeCampaignCashKey(current)===undefined)throw Error('Postava není účastníkem kalendáře.');
  // Validate AGAIN against persisted data inside the atomic mutation.
  if(acquisition==='buy'){if(activeCampaignCashKey(current)===undefined)throw Error('Postava není členem aktuální kampaně.');prepareLibraryPurchase(current,totalPrice,activeCampaignCashKey(current));}
  const invIds=[];
  for(const i of sources){const id=uuid();invIds.push(id);data.inventory.push({id,currentWQ:null,characterId:current.id,
   sourceItemId:i.id,snapshot:structuredClone(i),quantity:acquisition==='buy'?buyQuantity:1,condition:'',slot:'carried',
   ...(suitName?{printedSuitName:suitName}:{}),
   acquisition:{mode:acquisition,transactionId,at,pricePence:acquisition==='buy'?totalPrice:0,...(data.campaignClock?{campaignId:campaignKey(data.campaignClock),campaignMinute:data.campaignClock.minute}:{})}});}
  if(acquisition==='buy'){
   const key=activeCampaignCashKey(current);
   if(key!==null){recordCampaignCashPurchase(current,{campaignId:key,minute:data.campaignClock.minute,
    id:transactionId,at,amountPence:totalPrice,label:suitName||sources[0].name,inventoryIds:invIds,
    purchasedItems:sources.map((source,i)=>({inventoryId:invIds[i],sourceItemId:source.id,quantity:buyQuantity,snapshot:structuredClone(source)}))});}
   else{if(Object.keys(current.hmk?.campaignCashAccounts??{}).length)throw Error('Nákup vyžaduje aktivní kampaň.');current.hmk.cashLedger??=[];
    current.hmk.cashLedger.push({kind:'library-purchase',id:transactionId,at,amountPence:totalPrice,
      label:suitName||sources[0].name,inventoryIds:invIds});}
   if(!cashForCharacter(current).ok)throw Error('Nákup vytvořil neplatný zůstatek.');
  }
 });
 if(saved){const cash=cashForCharacter(character(receiver.id));notice=`${suitName?`Komplet ${suitName}: ${sources.length} součástí`:`${sources[0].name}`} ${acquisition==='buy'?`zakoupen${suitName?'':' '} za ${totalPrice}d (zbývá ${cash.balance}d)`:'převzat zdarma'} · postava ${receiver.name}. Vše je v inventáři jako nesené; zbroj ani zbraně nebyly automaticky vybaveny.`;render()}

},true);
document.addEventListener('input',e=>{if(e.target.closest?.('#impact-preview-form')){pendingMeleeTA=null;lastCombatEvent=null;for(const id of ['export-combat-draft','save-combat-draft']){const b=document.getElementById(id);if(b)b.disabled=true;}}if(e.target.id==='search'){query=e.target.value;libraryPage=0;const pos=e.target.selectionStart;render();const input=document.getElementById('search');input.focus();input.setSelectionRange(pos,pos)}});
document.addEventListener('change',async e=>{if(e.target.matches?.('form[data-library-form] select[name="recipientId"]')){libraryRecipientId=e.target.value;render();return;}if(e.target.closest?.('#impact-preview-form')){pendingMeleeTA=null;lastCombatEvent=null;for(const id of ['export-combat-draft','save-combat-draft']){const b=document.getElementById(id);if(b)b.disabled=true;}}if(e.target.id==='import-combat-session-file'){
 const f=e.target.files?.[0];if(!f)return;
 try{if(f.size>2_000_000)throw Error('Soubor je příliš velký (max. 2 MB).');const pkg=JSON.parse(await f.text());const parsed=parseCombatSessionImport(pkg,data.characters.map(c=>c.id));if(!ask(`Nahradit aktuální pracovní střetnutí (${parsed.history.length} událostí, ${parsed.participants.length} účastníků)? Postavy ani inventáře se nezmění.`))return;const r=restoreCombatSession(pkg);if(!r.ok)throw Error(r.reason);render();alert('Pracovní střetnutí bylo obnoveno.');}catch(err){alert('Obnova střetnutí odmítnuta: '+err.message)}finally{e.target.value=''}return;
 }if(e.target.id==='import-combat-history-file'){
 const f=e.target.files?.[0];if(!f)return;
 try{
  if(f.size>2_000_000)throw Error('Soubor je příliš velký (max. 2 MB).');
  const pkg=JSON.parse(await f.text());const mode=document.getElementById('import-combat-history-mode')?.value||'merge';
  const records=parseCombatHistoryImport(pkg);
  if(!ask(`Importovat ${records.length} návrhů (${mode==='replace'?'nahradit':'sloučit'})? Postavy se nezmění.`))return;
  const result=mergeCombatHistoryImport(pkg,mode);
  if(!result.ok)throw Error(result.reason);
  alert(`Import dokončen. ${mode==='merge'?`Přidáno ${result.added}, již existovalo ${result.skipped}.`:'Pracovní historie byla nahrazena.'}`);render();
 }catch(err){alert('Import historie odmítnut: '+err.message)}return;
 }if(e.target.id==='category'){category=e.target.value;render()}if(e.target.id==='catalog-status'){catalogStatus=e.target.value;libraryPage=0;render()}if(e.target.id==='import-character-file'){
 const f=e.target.files?.[0];if(!f)return;
 if(combatInitiativeSequence){e.target.value='';return alert('Během Initiative nelze importovat postavu ani její inventář mimo Combat průvodce.');}
 try{if(f.size>10*1024*1024)throw Error('Soubor přesahuje 10 MB');if(storageReadOnly)throw Error('Zápis je zablokován');const baselineBeforeImport=storageBaseline;const pkg=JSON.parse(await f.text());if(localStorage.getItem(STORAGE)!==baselineBeforeImport)throw Error('Data se mezitím změnila v jiné záložce. Obnovte stránku.');const incoming=importCharacterPackage(pkg);
 if(!ask(`Přidat postavu „${incoming.copy.name}“? Stávající postavy zůstanou zachovány. Importovaná postava dostane nové identifikátory.`))return;
 if(combatInitiativeSequence)throw Error('Během načítání začala Initiative; import byl zablokován.');
 if(mutate(()=>{if(combatInitiativeSequence)throw Error('Import inventáře do běžící Initiative není povolen.');(incoming.archived?data.trash:data.characters).push(incoming.copy);data.inventory.push(...incoming.inventory);data.journal.push(...incoming.journal)})){view='characters';selected=null;notice='Postava byla přidána ze zálohy.';render()}
 }catch(err){alert('Import postavy selhal: '+err.message)}finally{e.target.value=''}return;
 }
 if(e.target.id==='import-catalog-file'){
  const file=e.target.files?.[0];if(!file)return;
  try{
   if(storageReadOnly)throw Error('Úložiště je pouze pro čtení');
   if(file.size>10*1024*1024)throw Error('Katalog přesahuje 10 MB');
   const baseline=storageBaseline;
   const incoming=JSON.parse(await file.text());
   const pending=prepareCatalogImport(incoming,data.items);
   const collisions=catalogNameConflicts(pending,data.items);
   if(localStorage.getItem(STORAGE)!==baseline)throw Error('Data se mezitím změnila v jiné záložce. Obnovte stránku.');
   if(!pending.length){alert('Všechny položky katalogu již existují. Nebylo nic změněno.');return}
   if(!ask(`Přidat ${pending.length} nových položek do knihovny?${collisions.length?'\n\nPOZOR: '+collisions.length+' nových definic má stejný název a kategorii jako existující položka, ale odlišné parametry. Budou přidány jako samostatné varianty.\n'+collisions.slice(0,12).map(x=>'• '+x).join('\n')+(collisions.length>12?'\n…':''):''}\n\nExistující položky ani inventáře se nezmění.`))return;
   if(mutate(()=>data.items.push(...pending))){notice=`Do knihovny bylo přidáno ${pending.length} položek.`;view='library';render()}
  }catch(err){alert('Import katalogu selhal: '+err.message)}finally{e.target.value=''}
  return;
 }
 if(e.target.id==='import-file'){const f=e.target.files?.[0];if(!f)return;try{if(combatInitiativeSequence)throw Error('Import zálohy během běžící Initiative by mohl přepsat nedokončený boj a jeho trvalé následky. Nejprve bezpečně ukončete střetnutí.');if(f.size>10*1024*1024)throw Error('Záloha přesahuje limit 10 MB');const baselineBeforeImport=storageBaseline;const imported=validate(JSON.parse(await f.text()));if(localStorage.getItem(STORAGE)!==baselineBeforeImport)throw Error('Data se mezitím změnila v jiné záložce. Obnovte stránku.');if(storageReadOnly)throw Error('Import je zablokován kvůli nečitelným původním datům.');if(!ask('Import nahradí všechna současná data. Máte uloženou aktuální JSON zálohu? Pokračovat?'))return;if(combatInitiativeSequence)throw Error('Během načítání zálohy začala Initiative; nelze přepsat rozpracovaný boj.');const old=data;data=imported;if(!save({restoreBackup:true})){data=old;render();throw Error('Úložiště odmítlo zápis; původní data zůstala zachována')}selected=null;encounterSelection.clear();persistEncounterDraft();if(combatInitiativeSequence)persistInitiativeSequence(null);view='characters';notice='Import byl dokončen.';render() }catch(err){alert('Neplatný soubor zálohy: '+err.message)}}});


// HMK UI v2: source-grounded character attributes and editable equipment records.
// Rules PDF: Character sheet (Birth/Family/Persona/Standing/Attributes/Skills), pp. 38, 45.
const HMK_ATTRIBUTES={PHYSICAL:[['str','Strength'],['end','Endurance'],['dex','Dexterity'],['agl','Agility'],['per','Perception'],['cml','Comeliness']],MENTAL:[['aur','Aura'],['wil','Will'],['rea','Reasoning'],['cre','Creativity'],['emp','Empathy'],['elo','Eloquence']]};
const HMK_IDENTITY=[['folk','Folk'],['ageGroup','Age group'],['birthdate','Birthdate'],['sunsign','Sunsign'],['birthplace','Birthplace'],['society','Society'],['socialClass','Social class'],['familyOccupation','Parent occupation'],['background','Background'],['estrangement','Estrangement'],['morality','Morality'],['psyche','Psyche'],['home','Home'],['standing','Standing'],['complexion','Complexion'],['hair','Hair'],['eyes','Eyes'],['height','Height'],['weight','Weight'],['handedness','Handedness']];
function numericField(key,label,val){return `<label>${esc(label)}<input type="number" step="1" min="0" max="999" name="${esc(key)}" value="${esc(val??'')}"></label>`}
function hmkSheet(c){const h=c.hmk||{},live=persistentStateOf(c),authoritative=new Set(live.wounds.map(w=>w.id));return `<section class="panel wide"><h3>Zranění a stav postavy · Combat State</h3><p class="muted">Autoritativní potvrzené rány z Combat State, včetně lokality, závažnosti, Shock, Bleeder a léčení. Rozpracované náhledy zde nejsou.</p><p><strong>Shock: ${esc(live.shock)}</strong> · Krvácení: ${live.wounds.filter(w=>w.bleeding&&!w.healed).length} · Potvrzených ran: ${live.wounds.length}</p>${live.wounds.map(w=>`<div class="list-row"><div><b>${esc(w.location.toUpperCase())}${w.side?' / '+esc(w.side):''} · ${esc(w.severity+w.level)}</b> · ${esc(w.aspect)} · ${w.bleeding?'Bleeder · ':''}${w.healed?'ZHOJENO':w.healing?.infected?'INFEKCE':w.healing?.treated?'léčeno · další den '+esc(w.healing.nextHealingDay??'—'):'čeká na Treatment'}</div></div>`).join('')||'<p>Žádná potvrzená fyzická rána.</p>'}<details><summary>Starší ruční evidenční záznamy · oddělené od Combat State</summary>${(h.injuries||[]).filter(x=>!authoritative.has(x.id)).map(x=>`<div class="list-row"><div><b>${esc(x.location)}</b> · ${esc(x.description)} <span class="muted">${esc(x.severity)}</span></div><div class="actions"><button class="secondary" data-edit-injury="${esc(x.id)}">Upravit</button><button class="danger" data-remove-injury="${esc(x.id)}">Odstranit</button></div></div>`).join('')||'<p>Žádné.</p>'}</details><form id="hmk-injury-form"><div class="field-grid">${field('location','Lokalita zásahu')}${field('severity','Závažnost / označení')}${field('description','Popis poranění')}</div><button type="submit">Zapsat zranění</button></form></section>`}
function parseStructuredModes(raw){
 if(!String(raw||'').trim())return [];
 let x;try{x=JSON.parse(raw)}catch{throw Error('Režimy zbraně: neplatný JSON')}
 if(!Array.isArray(x)||x.length>30||x.some(m=>!m||typeof m!=='object'||Array.isArray(m)||!Object.keys(m).length))throw Error('Režimy musí být pole nejvýše 30 neprázdných objektů.');
 return x;
}
function parseStructuredTraits(raw){
 if(!String(raw||'').trim())return [];
 let x;try{x=JSON.parse(raw)}catch{throw Error('Traits: neplatný JSON')}
 if(!Array.isArray(x)||x.length>60||x.some(t=>typeof t!=='string'||!t.trim()))throw Error('Traits musí být pole neprázdných textů.');return x.map(t=>t.trim());
}
function parseLocationProtection(raw){
 if(!String(raw||'').trim())return {};
 let x;try{x=JSON.parse(raw)}catch{throw Error('Ochrana lokací: neplatný JSON')}
 if(!x||Array.isArray(x)||typeof x!=='object'||Object.keys(x).length>100)throw Error('Ochrana lokací musí být JSON objekt.');for(const [location,protection] of Object.entries(x)){if(!location.trim()||location.length>120||!protection||typeof protection!=='object'||Array.isArray(protection))throw Error('Každá lokalita musí obsahovat objekt ochranných hodnot.');if(Object.keys(protection).length>30)throw Error('Příliš mnoho typů ochrany u lokality '+location);for(const [aspect,value] of Object.entries(protection)){if(!aspect.trim()||!Number.isSafeInteger(value)||value<0||value>999)throw Error('Ochrana '+location+' / '+aspect+' musí být celé číslo 0–999.')}}return x;
}
function equipmentEditor(title,obj){const prop=obj.properties||{};const cat=obj.category||category;const specs=cat==='weapon'?[['attack','Útočné parametry (text)'],['defense','Obranné parametry (text)'],['impact','Impact / damage (text)'],['quality','Weapon Quality (WQ)'],['weightLb','Hmotnost v librách (lb)'],['traits','Traits / vlastnosti']]:cat==='shield'?[['defense','Obranné parametry (text)'],['quality','Shield Quality (WQ)'],['coverage','Krytí / použití'],['traits','Vlastnosti']]:cat==='armor'?[['material','Materiál'],['coverage','Pokryté lokace'],['layers','Vrstvy / články'],['protection','Ochranné hodnoty dle typu zásahu'],['quality','Kvalita / stav']]:[['weightLb','Hmotnost v librách (lb)'],['value','Cena / hodnota (text)'],['use','Použití / účel'],['notes','Poznámky']];return `<div class="panel"><h2>${esc(title)}</h2><form id="hmk-item-form">${field('name','Název',obj.name||'')}<label>Kategorie<select name="category">${[['weapon','Zbraň'],['shield','Štít'],['armor','Zbroj'],['other','Ostatní předmět']].map(([v,l])=>`<option value="${v}" ${cat===v?'selected':''}>${l}</option>`).join('')}</select></label>${area('description','Popis',obj.description||'')}${field('source','Pravidlový zdroj (strana/tabulka)',obj.source||'')}<div class="field-grid">${specs.map(([k,l])=>field('spec_'+k,l,prop[k]??'')).join('')}</div>${cat==='weapon'?`<div class="notice">Strukturované režimy a traits vyplňujte pouze podle ověřených HMK zdrojů. Prázdné pole = žádná ověřená data.</div>${area('verifiedModes','Ověřené režimy (JSON pole objektů)',JSON.stringify(prop.verifiedModes||[],null,2))}${area('verifiedTraits','Ověřené traits (JSON pole textů)',JSON.stringify(prop.verifiedTraits||[],null,2))}`:cat==='armor'?`<p class="muted">Formát: {"lokalita":{"typ_zásahu":ochrana}}. Názvy lokalit a typů zásahu přepište přesně z ověřeného HMK zdroje. Příklad struktury (nikoli hodnot pravidel): {"Example":{"B":1}}.</p>${area('locationProtection','Ověřené ochrany dle lokací (JSON objekt)',JSON.stringify(prop.locationProtection||{},null,2))}`:''}<p class="muted">Změna kategorie při editaci nepřepočítává pole; pro jiný typ založte nový záznam. Parametry jsou textové, aby se neinterpretovaly neověřené hodnoty.</p><div class="actions"><button type="submit">Uložit předmět</button><button type="button" class="secondary" data-action="cancel-editor">Zrušit</button></div></form></div>`}
// Bridge v3: serialize into the EXISTING HMK domain contracts. No combat calculations here.
function safeFilename(s){return String(s).normalize('NFKD').replace(/[^a-zA-Z0-9_-]+/g,'-').slice(0,50)||'character'}
// v32: spreadsheet-friendly, read-only audit. Escape delimiters and prevent CSV formula execution.
function safeCSVCell(value){
 const raw=String(value??'');
 // Excel may interpret leading =, +, -, @, tab or control whitespace as a formula.
 const safe=/^[\s\u0000-\u001f]*[=+\-@]/u.test(raw)?"'"+raw:raw;
 return '"'+safe.replace(/"/g,'""')+'"';
}
function catalogAuditCSV(){
 const rows=[['ID','Název','Kategorie','Zdroj HMK','Stav evidence','Chybějící údaje']];
 for(const e of catalogAuditReport().entries)rows.push([e.id,e.name,e.category,e.source||'',e.ready?'Bez upozornění':'K doplnění',e.missing.join('; ')]);
 return '\uFEFF'+rows.map(row=>row.map(safeCSVCell).join(';')).join('\r\n')+'\r\n';
}
function downloadCatalogAuditCSV(){
 const blob=new Blob([catalogAuditCSV()],{type:'text/csv;charset=utf-8'});
 const url=URL.createObjectURL(blob);const link=document.createElement('a');
 link.href=url;link.download='hmk-audit-katalogu-v32.csv';link.click();
 setTimeout(()=>URL.revokeObjectURL(url),5000);
}
function downloadJSON(value,filename){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function kernelExport(chars){
 const characterIds=new Set(chars.map(c=>c.id));
 const definitions=[];const instances=[];const used=new Set();const warnings=[];
 const characters=chars.map(c=>{
  const skills={};for(const skill of c.hmk?.skills||[]){const key=skill.id||kernelUUID();skills[key]=KernelSkill({id:key,key:skill.name,name:skill.name,ml:skill.ml??null,sb:skill.sb??null,group:skill.group||null});if(skill.ml===null||skill.ml===undefined)warnings.push('Dovednost '+skill.name+' u postavy '+c.name+' nemá ML.');}
  const attributes={...(c.hmk?.attributes||{})};
  if(!Object.keys(attributes).length)warnings.push('Postava '+c.name+' nemá zadané atributy.');
  return KernelCharacter({id:c.id,name:c.name,attributes,skills,handedness:c.hmk?.handedness==='left'?'left':'right',notes:c.description||''});
 });
 for(const inv of data.inventory.filter(x=>characterIds.has(x.characterId))){
  const src=inv.snapshot||{};const p=src.properties||{};const defId=src.id||inv.sourceItemId||inv.id;
  if(src.category==='weapon'){
   const normalized=combatStrikeModes(p);for(const issue of normalized.issues)warnings.push('Zbraň '+src.name+': '+issue);
   if(!used.has(defId)){definitions.push(WeaponDefinition({id:defId,name:src.name||'Unnamed',modes:normalized.modes,baseWQ:asNumber(p.quality),weightLb:asNonNegativeNumber(p.weightLb),traits:verifiedTraits(p)}));used.add(defId);}
   instances.push(WeaponInstance({id:inv.id,definitionId:defId,currentWQ:inv.currentWQ??asNumber(p.quality),baseWQ:asNumber(p.quality),ownerId:inv.characterId,custom:{quantity:inv.quantity,condition:inv.condition,unverifiedProperties:p}}));
   if(!normalized.modes.some(m=>m.kind==='primary'))warnings.push('Zbraň '+src.name+': chybí platný základní útočný režim.');
   if(p.traits&&!verifiedTraits(p).length)warnings.push('Zbraň '+src.name+': textové traits se nepřevádějí automaticky.');
  }else if(src.category==='shield'){
   const normalized=combatShieldInputs(p);for(const issue of normalized.issues)warnings.push('Štít '+src.name+': '+issue);
   instances.push(Shield({id:inv.id,definitionId:defId,currentWQ:inv.currentWQ??asNumber(p.quality),baseWQ:asNumber(p.quality),shieldMod:normalized.shieldModifier,deflect:normalized.deflect,ownerId:inv.characterId}));
   if(!normalized.modes.length)warnings.push('Štít '+src.name+': chybí platný útočný režim.');
  }else if(src.category==='armor'){
   const normalized=combatArmourInputs(p);
   for(const issue of normalized.issues)warnings.push('Zbroj '+src.name+': '+issue);
   instances.push(ArmourArticle({id:inv.id,definitionId:defId,ownerId:inv.characterId,locations:normalized.protection}));
  }
 }
 return {schemaVersion:SCHEMA_VERSION,format:'hmk-domain-bridge-v2',exportedAt:stamp(),characters,weaponDefinitions:definitions,equipmentInstances:instances,warnings};
}
function validatedProtection(raw){if(!raw||typeof raw!=='object'||Array.isArray(raw))return {};try{return parseLocationProtection(JSON.stringify(raw))}catch{return {}}}
function verifiedModes(p){return Array.isArray(p.verifiedModes)?p.verifiedModes.filter(x=>x&&typeof x==='object'&&!Array.isArray(x)).map(x=>structuredClone(x)):[]}
function verifiedTraits(p){return Array.isArray(p.verifiedTraits)?p.verifiedTraits.filter(x=>typeof x==='string'&&x.trim()).map(x=>x.trim()):[]}
function asNonNegativeNumber(v){if(v===null||v===undefined||String(v).trim()==="")return null;const n=Number(v);return Number.isFinite(n)&&n>=0?n:null}
function asNumber(v){if(v===null||v===undefined||String(v).trim()==='')return null;const n=Number(v);return Number.isSafeInteger(n)&&n>=0?n:null}

// v11: Form-based inventory editing with explicit category and slot validation.
function waterFillForm(x){
 const clock=data.campaignClock,key=campaignKey(clock),capacity=waterContainerCapacity(x);
 if(capacity===null)return '';
 const lots=clock?availableSupplyLots(data.journal,key).filter(l=>l.unit==='waterDays'&&l.remaining>=capacity&&l.minute<=clock.minute):[];
 const choices=lots.map(l=>`<option value="${esc(l.sourceId+'|'+l.resultIndex)}">Foraging · zdroj ${esc(l.sourceId)} / výsledek ${l.resultIndex+1} · k dispozici ${l.remaining} water-days</option>`).join('');
 return `<div class="editor-backdrop"><section class="panel editor-dialog" role="dialog" aria-modal="true"><h2>Naplnit ${esc(x.snapshot.name)}</h2><p class="muted">Skutečný objem ${capacity} gal pitné vody (+${capacity*10} lb). Nález Foraging se musí odečíst v tomto objemu; uložení není vypití. Čas GM beze změny.</p><form id="water-fill-form"><label>Zdroj skutečné vody<select name="foragingLot">${lots.length?`<option value="">Jiný doložený zdroj (GM)</option>${choices}`:'<option value="">Jiný doložený zdroj (GM) · žádný dostatečný Foraging nález</option>'}</select></label><label>Pokud zdroj není Foraging: kde byla voda získána?<input name="waterSource" maxlength="160" placeholder="Např. studna u domu, potok ověřený GM"></label><input type="hidden" name="itemId" value="${esc(x.id)}"><input type="hidden" name="actorId" value="${esc(x.characterId)}"><label><input type="checkbox" name="gmConfirmed" value="yes" required> GM ověřil skutečnou pitnou vodu, přístup k jejímu zdroji a naplnění nádoby</label><div class="actions"><button type="submit">Potvrdit naplnění</button><button type="button" data-action="cancel-editor" class="secondary">Zrušit</button></div></form></section></div>`;
}
function chestMoveForm(x){
 const stored=x.slot==='chest';const place=stored?x.chestLocation||'':'';
 return `<div class="editor-backdrop"><section class="panel editor-dialog" role="dialog" aria-modal="true" aria-labelledby="chest-move-title"><h2 id="chest-move-title">${stored?'Vyzvednout z Truhlice':'Uložit do Truhlice'} · ${esc(x.snapshot?.name||'Předmět')}</h2><p class="muted">Majetek zůstane postavě. Truhlice nepatří do nesené hmotnosti ani ENC. Po vyzvednutí bude předmět nesený, nikoli rovnou vybavený.</p><form id="chest-move-form"><input type="hidden" name="itemId" value="${esc(x.id)}"><input type="hidden" name="actorId" value="${esc(x.characterId)}"><label>Počet kusů (max. ${x.quantity})<input type="number" name="quantity" min="1" max="${x.quantity}" step="1" value="${x.quantity}" required></label><label>Skutečné místo Truhlice<input name="location" maxlength="160" value="${esc(place)}" placeholder="Např. vlastní dům v Tashálu" required ${stored?'readonly':''}></label><label><input name="accessConfirmed" type="checkbox" value="yes" required> GM potvrzuje, že postava má v tomto okamžiku k místu skutečný přístup</label><div class="actions"><button type="submit">${stored?'Vyzvednout':'Uložit'}</button><button type="button" class="secondary" data-action="cancel-editor">Zrušit</button></div></form></section></div>`;
}
function inventoryEditForm(x){return `<div class="editor-backdrop"><section class="panel editor-dialog" role="dialog" aria-modal="true" aria-labelledby="edit-inv-title"><h2 id="edit-inv-title">Upravit vybavení: ${esc(x.snapshot.name)}</h2><p class="muted">${esc(x.snapshot.category)} · Změny se projeví až po uložení.</p><form id="inventory-edit-form"><input type="hidden" name="inventoryId" value="${esc(x.id)}"><input type="hidden" name="ownerId" value="${esc(x.characterId)}">${numericField('quantity','Počet kusů',x.quantity)}${field('condition','Stav / poznámka',x.condition||'')}${numericField('currentWQ','Aktuální WQ (neznámá = prázdné)',x.currentWQ??'')}${slotSelect('slot',x.slot||'none')}<label>Způsob nesení (pro výbavu mimo zbroj na těle)<select name="gearStowage">${[['normal','Běžně'],['awkward','Nepohodlně (dvojnásobná hmotnost)'],['backpack','Uvnitř správně sbaleného batohu (poloviční hmotnost)']].map(([k,v])=>`<option value="${k}" ${x.gearStowage===k?'selected':''}>${v}</option>`).join('')}</select></label>${x.snapshot.category==='armor'?`${field('layerOrder','Pořadí vrstvy zevnitř ven (0–99, pouze pro vlastní sestavy)',x.layerOrder??'','number')}${field('bulkExceptionZones','GM Bulk výjimka: head,arms,torso,legs (pouze doložená výjimka HMK)',(x.bulkExceptionZones||[]).join(','))}<label>Sloupec vrstvy podle HMK p.117 (volitelný)<select name="layerSlot">${[['','Neurčen'],['underFar','Under far'],['underNear','Under near'],['base','Base'],['overNear','Over near'],['overFar','Over far']].map(([k,v])=>`<option value="${k}" ${x.layerSlot===k?'selected':''}>${v}</option>`).join('')}</select></label>`:''}<div class="actions"><button type="submit">Uložit změny</button><button type="button" class="secondary" data-action="cancel-editor">Zrušit</button></div></form></section></div>`}

// HMK v93.521: one atomic owner-bound outfit change; never overwrite hands,
// other characters, inventory records, or an in-progress combat Initiative.
document.addEventListener('click',e=>{
 const button=e.target?.closest?.('[data-outfit-action]');if(!button)return;
 e.preventDefault();e.stopImmediatePropagation();
 const action=button.dataset.outfitAction,ownerId=selected;
 if(view!=='sheet'||activeSheetSection!=='inventory'||!character(ownerId))return;
 if(combatInitiativeSequence)return alert('Během Initiative se výbava mění pouze pravidlovou Combat akcí.');
 if(action==='undress'){
  const worn=previewUndressOutfit(data.inventory,ownerId);
  if(!worn.length)return alert('Postava nemá žádné oblečené zbrojní či látkové články.');
  if(!ask('Svléknout '+worn.length+' článků? Všechny se přesunou mezi nesené předměty; žádné věci se neztratí.'))return;
  const before=JSON.stringify(data.inventory.filter(x=>x.characterId===ownerId));
  if(mutate(()=>{if(before!==JSON.stringify(data.inventory.filter(x=>x.characterId===ownerId)))throw Error('Inventář se změnil.');data.inventory=undressOutfit(data.inventory,ownerId);})){render();}
  return;
 }
 if(!['armour','clothing'].includes(action))return;
 const preview=previewOptimalOutfit(data.inventory,ownerId,action);
 if(!preview.ready)return alert('Automatické oblečení nelze bezpečně určit: '+preview.reason);
 if(!preview.placements.length)return alert('Žádný vhodný předmět.');
 try{if(JSON.stringify(applyOptimalOutfit(data.inventory,ownerId,preview))===JSON.stringify(data.inventory))return alert('Postava už má tuto nejlepší ověřenou kombinaci oblečenou.');}catch(err){return alert('Návrh nelze ověřit: '+err.message);}
 const confirmText=(preview.authoritativePreset?'Přesně ověřený tištěný komplet '+preview.printedSuit+':\n':'Pravidlově ověřená kombinace:\n')+preview.names.join(', ')+'\n\nSoučet ochrany B/E/P/F: '+preview.totalAV+', rigidní lokace: '+preview.rigidLocations+'\nNově obléknout: '+preview.equipIds.length+', svléknout: '+preview.unequipIds.length+'\nBulk: '+preview.bulkPenalty+', extra ENC: '+(preview.extraEnc??'zahrnuto v ENC tištěného kompletu')+'\n'+preview.proof+'\n\nProvést?';
 if(!ask(confirmText))return;
 try{
  const next=applyOptimalOutfit(data.inventory,ownerId,preview);
  // The authoritative combat-load evaluator must accept the exact final
  // inventory before any CAS write. No cosmetic success if load is invalid.
  const load=resolveCombatantLoad({character:character(ownerId),inventory:next});
  if((load.layeringFeasibility?.status==='forbidden'&&!load.printedSuit)||load.layeringStatus==='violation'||load.bulkReady===false)
   throw Error('Finální sestava neprošla kontrolou zatížení a vrstvení. '+(load.layeringStatus||''));
  if(mutate(()=>{data.inventory=next;})){render();}
 }catch(err){alert('Oblečení nebylo změněno: '+err.message);render();}
},true);
document.addEventListener('click',e=>{
 const t=e.target.closest('[data-armour-autolayer]');if(!t)return;
 e.preventDefault();e.stopImmediatePropagation();
 const id=t.dataset.armourAutolayer;
 if(view!=='sheet'||selected!==id||!character(id))return;
 if(combatInitiativeSequence)return alert('Během Initiative nelze bez Combat akce měnit vrstvení.');
 const current=data.inventory.filter(x=>x.characterId===id);
 const preview=previewExistingArmourArrangement(current);
 if(!preview.ready)return alert(preview.reason);
 if(!preview.placements.length)return;
 const original=resolveCombatantLoad({character:character(id),inventory:activeRationInventory()});
 if(original.layeringFeasibility?.status==='forbidden')return alert('Skutečně zakázané vrstvy nelze pouhým přeuspořádáním legalizovat.');
 if(!ask('Zapsat automaticky ověřené pořadí oblečených vrstev? Žádný předmět nebude odebrán ani přesunut.'))return;
 const done=mutate(()=>{
  const targets=new Map(preview.placements.map(x=>[x.id,x]));
  for(const item of data.inventory){if(item.characterId!==id||!targets.has(item.id))continue;
   const p=targets.get(item.id);if(item.slot!=='worn')throw Error('Během rozhodnutí se změnilo oblečení');
   item.layerOrder=p.layerOrder;item.layerSlot=p.layerSlot;item.bulkExceptionZones=[...p.bulkExceptionZones];
  }
  const verified=resolveCombatantLoad({character:character(id),inventory:activeRationInventory()});
  if(!verified.bulkReady||!verified.encReady||verified.layeringStatus==='violation')throw Error('Nové pořadí neprošlo pravidlovou kontrolou HMK');
 });
 if(done){selected=id;view='sheet';render();}
},true);
// Persisted grip is the single authority for hand reservations and combat.
document.addEventListener('change',e=>{
 const ctrl=e.target?.closest?.('[data-weapon-grip]');if(!ctrl)return;
 e.stopImmediatePropagation();
 const ownerId=selected;
 if(view!=='sheet'||activeSheetSection!=='inventory'||!character(ownerId)||combatInitiativeSequence){render();return;}
 try{
  const next=setWeaponGrip(data,{ownerId,itemId:ctrl.dataset.weaponGrip,grip:ctrl.value});
  if(!mutate(()=>{data.inventory=next.inventory;}))render();
 }catch(err){alert('Držení nebylo změněno: '+err.message);render();}
},true);
// Equipment dropdown writes to the SAME authoritative inventory used by Combat.
// Never equip during active Initiative, never silently replace an occupied hand.
document.addEventListener('change',e=>{
 const ctrl=e.target?.closest?.('[data-equip-hand]');if(!ctrl)return;
 e.stopImmediatePropagation();
 const slot=ctrl.dataset.equipHand,id=String(ctrl.value||''),ownerId=selected;
 if(view!=='sheet'||activeSheetSection!=='inventory'||!character(ownerId))return;
 if(combatInitiativeSequence){alert('Během Initiative vybavujte pouze pravidlově potvrzenou Combat akcí.');render();return;}
 try{
  const updated=equipInventoryHand(data,{ownerId,slot,itemId:id,newItemId:uuid()});
  // The existing CAS writer persists inventory only; it does not rewrite actors.
  if(!mutate(()=>{data.inventory=updated.inventory;}))render();
 }catch(err){alert('Ruce nebyly změněny: '+err.message);render();}
},true);
// One compact inventory action picker. Dispatch to the pre-existing handlers,
// not a second implementation of chest, transfer, edit, or item disposal.
document.addEventListener('click',e=>{
 const ok=e.target.closest?.('[data-inv-action-confirm]');if(!ok)return;
 e.preventDefault();e.stopImmediatePropagation();
 const menu=ok.closest('[data-inv-action-menu]'),select=menu?.querySelector('[data-inv-action-select]');
 const option=select?.selectedOptions[0],kind=select?.value,id=menu?.querySelector('[data-inv-member-select]')?.value||ok.dataset.invItemId;
 const x=data.inventory.find(i=>i.id===id&&i.characterId===selected);
 if(!kind||!x||view!=='sheet'||activeSheetSection!=='inventory')return;
 if(kind==='partial'){
  if(combatInitiativeSequence)return alert('Během Initiative nelze zásoby odložit bez Combat akce.');
  overlay=inventoryPartialDropForm(x);
  if(!overlay)return alert('Na tomto předmětu není doložená odložitelná zásoba.');
  render();return;
 }
 const attrs={edit:'data-edit-inv',chest:'data-chest-move','ration-transfer':'data-transfer-ration',
  'ration-loss':'data-loss-ration',transfer:'data-transfer-inv',remove:'data-remove-inv'};
 const attr=attrs[kind];if(!attr)return;
 const key=campaignKey(data.campaignClock),minute=data.campaignClock?.minute??0;
 const source=kind==='ration-transfer'?availableRationLots(data.journal,key,selected,minute).find(l=>l.itemId===id)?.sourceId:
  kind==='ration-loss'?rationStockBalances(data.journal,key,selected,minute).find(l=>l.itemId===id&&l.minute<=minute&&l.remaining>=0.5)?.sourceId:null;
 const target=kind==='ration-transfer'||kind==='ration-loss'?source:id;
 if((kind==='ration-transfer'||kind==='ration-loss')&&!target)return alert('Vybraný konkrétní kus nemá pro tuto akci dostupné doložené potraviny.');
 if(!target)return;
 const route=document.createElement('button');route.type='button';route.hidden=true;route.setAttribute(attr,target);
 menu.append(route);
 try{route.click();}finally{route.remove();}
},true);
document.addEventListener('change',e=>{
 const pick=e.target.closest?.('[data-inv-partial-lot]');if(!pick)return;
 const field=pick.closest('form')?.querySelector('[data-inv-partial-quantity]');if(!field)return;
 const remaining=Number(pick.selectedOptions[0]?.dataset.remaining||0);
 field.max=String(remaining);if(Number(field.value)>remaining||Number(field.value)<0.5)field.value='0.5';
},true);
document.addEventListener('submit',e=>{
 if(e.target?.id!=='inventory-partial-drop-form')return;
 e.preventDefault();e.stopImmediatePropagation();
 try{
  if(view!=='sheet'||activeSheetSection!=='inventory'||combatInitiativeSequence)throw Error('Odložení není v aktuálním režimu dostupné.');
  const fd=new FormData(e.target),clock=data.campaignClock,actorId=String(fd.get('actorId')||''),itemId=String(fd.get('itemId')||'');
  if(!clock||actorId!==selected)throw Error('Změnila se postava nebo kampaň.');
  const x=data.inventory.find(i=>i.id===itemId&&i.characterId===actorId&&i.slot!=='chest');
  if(!x)throw Error('Předmět již není nesený touto postavou.');
  const select=e.target.querySelector('[data-inv-partial-lot]'),chosen=select?.selectedOptions[0],kind=chosen?.dataset.kind;
  const sourceId=String(fd.get('sourceId')||''),quantity=Number(fd.get('quantity'));
  if(!Number.isFinite(quantity)||quantity<0.5||!Number.isSafeInteger(quantity*2))throw Error('Zvolte násobek půl dávky / 0,5 gal.');
  const common={actorId,quantity,eventId:uuid(),campaignId:campaignKey(clock),minute:clock.minute,
   reason:String(fd.get('reason')||''),confirmedByGM:true,createdAt:stamp()};
  let next;
  if(kind==='food'){
   const lot=rationStockBalances(data.journal,common.campaignId,actorId,clock.minute).find(l=>l.sourceId===sourceId&&l.itemId===itemId&&l.remaining>=quantity);
   if(!lot)throw Error('Doložené potraviny již nejsou v této položce dostupné.');
   next=recordPhysicalRationLoss(data,{...common,sourceId});
  }else if(kind==='water'){
   const lot=waterskinBalances(data.journal,common.campaignId,actorId,clock.minute).find(l=>l.fillId===sourceId&&l.itemId===itemId&&l.remaining>=quantity);
   if(!lot)throw Error('Doložené naplnění již v této nádobě není dostupné.');
   next=recordPhysicalWaterLoss(data,{...common,fillId:sourceId});
  }else throw Error('Neplatná zásoba.');
  if(mutate(()=>{data.journal=next.journal;})){overlay=null;render();}
 }catch(error){alert('Odložení nebylo uloženo: '+error.message)}
},true);
